alter table concierge.checkin_reports alter column comfort drop not null,alter column consistency drop not null,alter column changes drop not null;
alter table concierge.checkin_reports add constraint review_report_format check(
 (report_format='legacy' and comfort is not null and consistency is not null and changes is not null)
 or (report_format='goal' and comfort is null and consistency is null and changes is null));
create table concierge.review_goal_reports(report_id uuid primary key,client_id uuid not null,body jsonb not null,occurred_on jsonb not null,recorded_at timestamptz not null,recorded_by uuid not null,foreign key(client_id,report_id) references concierge.checkin_reports(client_id,id) on delete cascade deferrable initially deferred);
create table concierge.review_conversations(id uuid primary key,client_id uuid not null references concierge.cases on delete cascade,body jsonb not null,recorded_by uuid not null,recorded_at timestamptz not null);
create table concierge.review_report_amendments(id uuid primary key,client_id uuid not null,report_id uuid not null,report_kind text not null check(report_kind in ('goal_report','legacy_report')),previous_id uuid references concierge.review_report_amendments,body jsonb not null,recorded_by uuid not null,recorded_at timestamptz not null,foreign key(client_id,report_id) references concierge.checkin_reports(client_id,id) on delete cascade);
create unique index review_one_report_successor on concierge.review_report_amendments(report_id,coalesce(previous_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table concierge.review_private_notes(id uuid primary key,client_id uuid not null references concierge.cases on delete cascade,subject jsonb not null,note text not null,recorded_by uuid not null,recorded_at timestamptz not null,sequence bigint generated always as identity);
create table concierge.review_amendment_photos(amendment_id uuid not null references concierge.review_report_amendments on delete cascade,photo_id uuid not null references concierge.checkin_photos on delete cascade,primary key(amendment_id,photo_id));
create table concierge.review_guidance_drafts(id uuid primary key,client_id uuid not null references concierge.cases on delete cascade,kind text not null check(kind in ('review','instruction','reply')),revision bigint not null check(revision between 1 and 9007199254740991));
create table concierge.review_guidance_revisions(draft_id uuid not null references concierge.review_guidance_drafts on delete cascade,revision bigint not null,body jsonb not null,basis jsonb not null,target jsonb not null,actor_id uuid not null,recorded_at timestamptz not null,primary key(draft_id,revision));
create table concierge.review_guidance_reviews(id uuid primary key,draft_id uuid not null,revision bigint not null,target jsonb not null,actor_id uuid not null,recorded_at timestamptz not null,foreign key(draft_id,revision) references concierge.review_guidance_revisions on delete cascade);
create table concierge.review_guidance_approvals(id uuid primary key,draft_id uuid not null,revision bigint not null,target jsonb not null,publisher jsonb not null,scope text not null check(scope in ('review.publish','instruction.publish','reply.publish')),approved_by uuid not null,approved_at timestamptz not null,policy_revision bigint not null,foreign key(draft_id,revision) references concierge.review_guidance_revisions on delete cascade);
create table concierge.review_guidance_revocations(approval_id uuid primary key references concierge.review_guidance_approvals on delete cascade,actor_id uuid not null,recorded_at timestamptz not null,policy_revision bigint not null);
create table concierge.review_guidance_outputs(id uuid primary key,client_id uuid not null references concierge.cases on delete cascade,kind text not null check(kind in ('review','instruction','reply')),draft_id uuid not null,revision bigint not null,approval_id uuid not null unique references concierge.review_guidance_approvals on delete cascade,body jsonb not null,basis jsonb not null,target jsonb not null,publisher jsonb not null,receipt_id uuid not null unique,event_id uuid not null unique,output_version bigint not null default 1,original_start jsonb,recorded_at timestamptz not null,foreign key(draft_id,revision) references concierge.review_guidance_revisions on delete cascade);
create table concierge.review_guidance_receipts(id uuid primary key,client_id uuid not null references concierge.cases on delete cascade,output_id uuid not null unique references concierge.review_guidance_outputs on delete cascade deferrable initially deferred,approval_id uuid not null unique references concierge.review_guidance_approvals on delete cascade,event_id uuid not null unique references concierge.plan_events on delete cascade deferrable initially deferred,actor_id uuid not null,request_id uuid not null,receipt jsonb not null);
alter table concierge.review_guidance_outputs add foreign key(receipt_id) references concierge.review_guidance_receipts deferrable initially deferred,add foreign key(event_id) references concierge.plan_events deferrable initially deferred;
create table concierge.review_attention(id uuid primary key,client_id uuid not null references concierge.cases on delete cascade,amendment_id uuid not null references concierge.review_report_amendments on delete cascade,prior_review_id uuid not null references concierge.review_guidance_outputs on delete cascade,publication_version integer not null,recorded_at timestamptz not null,unique(amendment_id,prior_review_id));
create table concierge.review_attention_events(id uuid primary key,attention_id uuid not null references concierge.review_attention on delete cascade,resolved_by uuid references concierge.review_guidance_outputs on delete cascade,recorded_at timestamptz not null);
