create table concierge.review_requests(actor_id uuid not null references auth.users on delete cascade,request_id uuid not null,client_id uuid not null references concierge.cases on delete cascade,family text not null check(family in ('review','guidance')),command jsonb not null,result jsonb not null,recorded_at timestamptz not null default clock_timestamp(),primary key(actor_id,request_id));
-- Association proof only, not another choice ledger. Existing historical rows are not backfilled.
create table concierge.review_decision_provenance(client_id uuid not null references concierge.cases on delete cascade,publication_version integer not null,decision_id text not null,decision_revision bigint not null,actor_id uuid not null,request_id uuid not null,family text not null check(family in ('plan_v1','review_v2')),row_hash text not null,primary key(client_id,decision_revision),unique(actor_id,request_id));

