create function concierge.review_compact(v jsonb) returns text language plpgsql immutable set search_path='' as $$declare r text;begin
 if jsonb_typeof(v)='object' then select '{'||coalesce(string_agg(to_jsonb(k)::text||':'||concierge.review_compact(x),',' order by k),'')||'}' into r from jsonb_each(v) e(k,x);return r;
 elsif jsonb_typeof(v)='array' then select '['||coalesce(string_agg(concierge.review_compact(x),',' order by n),'')||']' into r from jsonb_array_elements(v) with ordinality e(x,n);return r;
 else return v::text;end if;
end $$;
create function concierge.review_bytes(v jsonb) returns integer language sql immutable set search_path='' as $$ select octet_length(convert_to(concierge.review_compact(v),'UTF8')) $$;
