 elsif s->>'type'='object' then r:='{}';for k,f in select * from jsonb_each(s->'fields') loop if v?k then r:=r||jsonb_build_object(k,concierge.review_shape_value(v->k,f));end if;end loop;return r;
 elsif s->>'type'='array' then r:='[]';for x in select value from jsonb_array_elements(v) loop r:=r||jsonb_build_array(concierge.review_shape_value(x,s->'item'));end loop;return r;
 elsif s->>'type'='union' then for f in select value from jsonb_array_elements(s->'variants') loop begin perform concierge.plan_shape(v,f);return concierge.review_shape_value(v,f);exception when raise_exception then null;end;end loop;perform concierge.fail('invalid_input');
 end if;return v;
end $$;
create function concierge.review_parse(v jsonb,family text) returns jsonb language plpgsql immutable set search_path='' as $$declare fields jsonb;a text:=v->>'action';begin
 fields:=case family when 'review' then concierge.review_command_fields() when 'guidance' then concierge.guidance_command_fields() end;
 if fields is null or a is null or not(fields?a) or concierge.review_bytes(v)>500000 then perform concierge.fail('invalid_input');end if;
