end $$;
create function concierge.review_request_collision() returns trigger language plpgsql set search_path='' as $$declare t text;exists_other boolean;begin
 perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||new.actor_id::text||':'||new.request_id::text,0));
 foreach t in array array['plan_requests','requests','workflow_requests','care_requests','review_requests'] loop
  if t=TG_TABLE_NAME then continue;end if;
  execute format('select exists(select 1 from concierge.%I where actor_id=$1 and request_id=$2)',t) into exists_other using new.actor_id,new.request_id;
  if exists_other then perform concierge.fail('request_conflict');end if;
 end loop;return new;
end $$;
do $$declare t text;begin foreach t in array array['plan_requests','requests','workflow_requests','care_requests','review_requests'] loop execute format('create trigger review_request_collision before insert on concierge.%I for each row execute function concierge.review_request_collision()',t);end loop;end $$;
