 if (select count(distinct value) from jsonb_array_elements(ids))<>jsonb_array_length(ids) then perform concierge.fail('invalid_input');end if;
 for pid in select value from jsonb_array_elements(ids) loop
  select * into p from concierge.checkin_photos where id=(pid#>>'{}')::uuid and client_id=c for share;
  if not found or p.state<>'complete' or exists(select 1 from concierge.report_photos where photo_id=p.id and report_id is distinct from report) or exists(select 1 from concierge.review_amendment_photos ap join concierge.review_report_amendments am on am.id=ap.amendment_id where ap.photo_id=p.id and am.report_id is distinct from report) then perform concierge.fail('photo_unavailable');end if;
 end loop;
end $$;
create function concierge.review_goal_check(c uuid,b jsonb,report uuid default null) returns void language plpgsql set search_path='' as $$declare d jsonb;x jsonb;begin
 perform concierge.plan_shape(b,concierge.review_shapes()->'goal');if concierge.review_bytes(b)>90000 then perform concierge.fail('invalid_input');end if;
 perform concierge.review_require_publication(c,b->'publication');d:=concierge.review_document(c,b->'publication');
 if (select count(distinct value->>'goalId') from jsonb_array_elements(b->'answers'))<>jsonb_array_length(b->'answers') then perform concierge.fail('invalid_input');end if;
 for x in select value from jsonb_array_elements(b->'answers') loop if not exists(select 1 from jsonb_array_elements(d->'content'->'goals') g where g->'id'=x->'goalId') then perform concierge.fail('not_found');end if;end loop;
 for x in select value from jsonb_array_elements(b->'actualUseEventIds') loop if not exists(select 1 from concierge.care_events where client_id=c and id=(x#>>'{}')::uuid and kind in ('use','reported_product')) then perform concierge.fail('not_found');end if;end loop;
 if (select count(distinct value) from jsonb_array_elements(b->'actualUseEventIds'))<>jsonb_array_length(b->'actualUseEventIds') then perform concierge.fail('invalid_input');end if;
 perform concierge.review_photos(c,b->'photoIds',report);
end $$;
create function concierge.review_report_event(c uuid,rid uuid) returns jsonb language plpgsql set search_path='' as $$declare r concierge.checkin_reports;d concierge.review_goal_reports;photos jsonb;begin
 select * into r from concierge.checkin_reports where id=rid and client_id=c;if not found then perform concierge.fail('not_found');end if;
 if r.report_format='goal' then select * into d from concierge.review_goal_reports where report_id=rid and client_id=c;if not found then perform concierge.fail('incomplete_publication');end if;return jsonb_build_object('kind','goal_report','id',rid,'body',d.body,'occurredOn',d.occurred_on,'channel','portal','reportedBy',c,'recordedBy',d.recorded_by,'recordedAt',concierge.care_instant(d.recorded_at));end if;
 select coalesce(jsonb_agg(photo_id order by photo_id),'[]') into photos from concierge.report_photos where report_id=rid;
 return jsonb_build_object('kind','legacy_report','id',rid,'body',jsonb_build_object('comfort',r.comfort,'consistency',r.consistency,'changes',r.changes,'photoIds',photos),'occurredOn',jsonb_build_object('state','unknown'),'channel','portal','reportedBy',c,'recordedBy',c,'recordedAt',concierge.care_instant(r.submitted_at));
end $$;
create function concierge.review_notify(c uuid,e uuid,v integer,h bigint,kind text,recipient uuid default null) returns uuid language plpgsql set search_path='' as $$declare id uuid;r record;begin
 insert into concierge.plan_events(client_id,publication_version,kind,source_kind,source_id,source_version) values(c,v,kind,case when recipient is null then 'review' else 'guidance' end,e,h) returning plan_events.id into id;
 if recipient is not null then insert into concierge.plan_deliveries(event_id,recipient_id,channel) values(id,recipient,'portal'),(id,recipient,'email');return id;end if;
 perform 1 from concierge.care_attention_routes where client_id=c order by advisor_id for share;
 for r in select pr.actor_id,coalesce(rt.email_enabled,false) email_enabled from concierge.plan_principals pr join concierge.advisors ad on ad.user_id=pr.actor_id left join concierge.care_attention_routes rt on rt.advisor_id=pr.actor_id and rt.client_id=c where pr.active and pr.kind in ('owner','human') and ad.active and ad.can_view and (rt.advisor_id is not null or (not exists(select 1 from concierge.care_attention_routes where client_id=c) and pr.kind='owner' and pr.actor_id=(select owner_actor_id from concierge.plan_policy where singleton))) order by pr.actor_id loop
  if not concierge.plan_read_human_live(r.actor_id) then continue;end if;
  insert into concierge.plan_deliveries(event_id,recipient_id,channel) values(id,r.actor_id,'portal');if r.email_enabled then insert into concierge.plan_deliveries(event_id,recipient_id,channel) values(id,r.actor_id,'email');end if;
 end loop;return id;
end $$;

create function concierge.review_conversation_sources(b jsonb) returns jsonb language sql immutable set search_path='' as $$
 select coalesce(jsonb_agg(loc),'[]') from (select value f from jsonb_array_elements(b->'clientReported') union all select value from jsonb_array_elements(b->'advisorConclusions') union all select value from jsonb_array_elements(b->'agentProposals')) facts cross join lateral jsonb_array_elements(f->'sources') loc
$$;
create function concierge.review_conversation_check(c uuid,b jsonb) returns void language plpgsql set search_path='' as $$declare ref jsonb;facts jsonb;begin
 perform concierge.plan_shape(b,concierge.review_shapes()->'conversation');if concierge.review_bytes(b)>250000 then perform concierge.fail('invalid_input');end if;
 perform concierge.review_require_publication(c,b->'publication');perform concierge.care_occurrence(b->'occurredOn');
 facts:=(b->'clientReported')||(b->'advisorConclusions')||(b->'agentProposals');
 if jsonb_array_length(facts)>50 or (select count(distinct value->>'id') from jsonb_array_elements(facts))<>jsonb_array_length(facts) then perform concierge.fail('invalid_input');end if;
 for ref in select value->'left' from jsonb_array_elements(b->'contradictions') union all select value->'right' from jsonb_array_elements(b->'contradictions') loop
  if not exists(select 1 from jsonb_array_elements(b->case ref->>'kind' when 'client_report' then 'clientReported' when 'advisor_conclusion' then 'advisorConclusions' else 'agentProposals' end) f where f->'id'=ref->'id') then perform concierge.fail('invalid_input');end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(b->'contradictions') x where x->'left'=x->'right') then perform concierge.fail('invalid_input');end if;
 perform concierge.review_source_check(c,concierge.review_conversation_sources(b));
end $$;
create function concierge.review_report_complete() returns trigger language plpgsql security definer set search_path='' as $$declare d concierge.review_goal_reports;req concierge.review_requests;begin
 if new.report_format='legacy' then
  if (select activated from concierge.plan_policy where singleton) then perform concierge.fail('content_version_required');end if;return null;
 end if;
 if auth.uid() is distinct from new.client_id then perform concierge.fail('forbidden');end if;perform concierge.review_guard(new.client_id,false,true);
 select * into d from concierge.review_goal_reports where report_id=new.id and client_id=new.client_id;
 if not found or d.recorded_by<>new.client_id or concierge.review_has_observation(d.body) is not true or d.recorded_at<>new.submitted_at then perform concierge.fail('incomplete_publication');end if;
 perform concierge.review_goal_check(new.client_id,d.body,new.id);perform concierge.plan_shape(d.occurred_on,concierge.review_command_fields()->'submit_goal_report_v1'->'occurredOn');perform concierge.care_occurrence(d.occurred_on);
 select * into req from concierge.review_requests where client_id=new.client_id and result->>'action'='submit_goal_report_v1' and result->'event'->>'id'=new.id::text;
 if not found or req.actor_id<>new.client_id or not exists(select 1 from concierge.plan_events e where e.id=(req.result->>'notificationEventId')::uuid and e.client_id=new.client_id and e.source_kind='review' and e.source_id=new.id) then perform concierge.fail('incomplete_publication');end if;
 return null;
end $$;
create constraint trigger review_report_complete after insert on concierge.checkin_reports deferrable initially deferred for each row execute function concierge.review_report_complete();
create function concierge.review_goal_detail_complete() returns trigger language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from concierge.checkin_reports where id=new.report_id and client_id=new.client_id and report_format='goal') then perform concierge.fail('incomplete_publication');end if;return null;
end $$;
create constraint trigger review_goal_detail_complete after insert on concierge.review_goal_reports deferrable initially deferred for each row execute function concierge.review_goal_detail_complete();
create function concierge.review_note_subject(c uuid,s jsonb) returns void language plpgsql set search_path='' as $$begin
 if s->>'kind' in ('legacy_report','goal_report') then if concierge.review_report_event(c,(s->>'id')::uuid)->'kind' is distinct from s->'kind' then perform concierge.fail('not_found');end if;
 elsif s->>'kind'='conversation' then if not exists(select 1 from concierge.review_conversations where id=(s->>'id')::uuid and client_id=c) then perform concierge.fail('not_found');end if;perform concierge.review_source_check(c,(select concierge.review_conversation_sources(body) from concierge.review_conversations where id=(s->>'id')::uuid and client_id=c));
 elsif s->>'kind'='review' then if not exists(select 1 from concierge.review_guidance_outputs where id=(s->>'id')::uuid and client_id=c and kind='review') then perform concierge.fail('not_found');end if;
 else perform concierge.fail('invalid_input');end if;
end $$;
create function concierge.review_request_authorize(r concierge.review_requests) returns void language plpgsql set search_path='' as $$declare advisor boolean;body jsonb;begin
 advisor:=r.family='guidance' or r.command?'clientId';perform concierge.review_guard(r.client_id,advisor,false,advisor);
 if r.command->>'action'='record_conversation_v1' then perform concierge.review_source_check(r.client_id,concierge.review_conversation_sources(r.command->'body'));
 elsif r.family='guidance' then
  if r.result?'draft' then body:=r.result->'draft'->'body';
  elsif r.command?'target' then select rev.body into body from concierge.review_guidance_revisions rev where rev.draft_id=(r.command->'target'->>'draftId')::uuid and rev.revision=(r.command->'target'->>'revision')::bigint;
  elsif r.command?'approvalId' then select rev.body into body from concierge.review_guidance_approvals ap join concierge.review_guidance_revisions rev on rev.draft_id=ap.draft_id and rev.revision=ap.revision where ap.id=(r.command->>'approvalId')::uuid;end if;
  if body is null then perform concierge.fail('source_conflict');end if;perform concierge.review_guidance_sources_check(r.client_id,body);
 elsif r.command->>'action'='append_private_review_note_v1' then perform concierge.review_note_subject(r.client_id,r.command->'reviewEvent');end if;
 if r.command->>'action'='publish_guidance_v1' then perform concierge.capability(auth.uid(),'publish');end if;
 perform concierge.review_guard(r.client_id,advisor,false,advisor);
end $$;
create function concierge.review_amendment_json(a concierge.review_report_amendments) returns jsonb language sql set search_path='' as $$
 select jsonb_build_object('id',a.id,'event',jsonb_build_object('kind',a.report_kind,'id',a.report_id),'previousAmendmentHeadId',a.previous_id,'replacement',a.body->'replacement','occurredOn',a.body->'occurredOn','reason',a.body->'reason','amendedBy',a.recorded_by,'recordedAt',concierge.care_instant(a.recorded_at),'attention',null)
$$;
create function concierge.review_legacy_instruction_json(d concierge.instruction_drafts,p concierge.instruction_publications) returns jsonb language sql set search_path='' as $$select jsonb_build_object('id',p.id,'version',p.version,'slot',d.data->'slot','productId',d.data->'productId','planVersion',d.data->'planVersion','usage',jsonb_build_object('periods',d.data->'usage'->'periods','order',d.data->'usage'->'order','short',jsonb_build_object('morning',d.data->'usage'->'short'->'morning','evening',d.data->'usage'->'short'->'evening'),'instructions',d.data->'usage'->'instructions'),'reason',d.data->'reason','reviewId',d.data->'reviewId','effectiveOn',d.data->'effectiveOn','source',jsonb_build_object('kind',d.source->'kind','publicationVersion',d.source->'publicationVersion','recommendationId',d.source->'recommendationId'),'originalStartedOn',d.original_started_on,'authorId',p.actor_id,'createdAt',concierge.care_instant(p.created_at))$$;
create function concierge.review_is_published(o concierge.review_guidance_outputs) returns boolean language sql set search_path='' as $$select exists(select 1 from concierge.review_guidance_receipts r where r.id=o.receipt_id and r.output_id=o.id and r.client_id=o.client_id and r.approval_id=o.approval_id and r.event_id=o.event_id) and case o.kind when 'review' then exists(select 1 from concierge.service_reviews c where c.id=o.id and c.client_id=o.client_id and c.data=o.body and c.actor_id=(o.publisher->>'actorId')::uuid) when 'instruction' then exists(select 1 from concierge.instruction_publications p join concierge.instruction_drafts d on d.id=p.draft_id where p.id=o.id and p.client_id=o.client_id and p.draft_id=o.draft_id and p.version=o.output_version and d.data=o.body) else exists(select 1 from concierge.checkin_replies r where r.id=o.id and r.client_id=o.client_id and r.report_id=(o.body->'reportRef'->>'id')::uuid and r.reply=o.body->>'reply' and r.created_by=(o.publisher->>'actorId')::uuid) end$$;
create function concierge.review_cursor_key(domain text,key text) returns uuid language sql immutable set search_path='' as $$select (substr(h,1,8)||'-'||substr(h,9,4)||'-5'||substr(h,14,3)||'-8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid from (select md5(domain||':'||key) h) q$$;
create function concierge.review_history_item(c uuid,kind text,eid uuid) returns jsonb language plpgsql set search_path='' as $$declare r record;e concierge.care_events;am concierge.review_report_amendments;body jsonb;begin
 if kind='report' then return jsonb_build_object('kind','report','event',concierge.review_report_event(c,eid));
 elsif kind='report_amendment' then select * into am from concierge.review_report_amendments where review_report_amendments.id=eid and client_id=c;return jsonb_build_object('kind',kind,'original',concierge.review_report_event(c,am.report_id),'amendment',concierge.review_amendment_json(am));
 elsif kind='conversation' then select * into r from concierge.review_conversations where review_conversations.id=eid and client_id=c;perform concierge.review_source_check(c,concierge.review_conversation_sources(r.body));return jsonb_build_object('kind',kind,'event',jsonb_build_object('id',r.id,'body',r.body,'reportedBy',c,'recordedBy',r.recorded_by,'recordedAt',concierge.care_instant(r.recorded_at)));
 elsif kind='private_note' then select * into r from concierge.review_private_notes where review_private_notes.id=eid and client_id=c;if found then return jsonb_build_object('kind',kind,'note',jsonb_build_object('id',r.id,'reviewEvent',r.subject,'note',r.note,'recordedBy',r.recorded_by,'recordedAt',concierge.care_instant(r.recorded_at)));end if;select n.id,n.note,n.created_by,n.created_at,n.report_id,x.report_format into r from concierge.checkin_notes n join concierge.checkin_reports x on x.id=n.report_id and x.client_id=n.client_id where n.id=eid and n.client_id=c;return jsonb_build_object('kind',kind,'note',jsonb_build_object('id',r.id,'reviewEvent',jsonb_build_object('kind',case when r.report_format='goal' then 'goal_report' else 'legacy_report' end,'id',r.report_id),'note',r.note,'recordedBy',r.created_by,'recordedAt',concierge.care_instant(r.created_at)));
 elsif kind='legacy_review_note' then select n.review_id,n.note into r from concierge.service_review_private n join concierge.service_reviews sr on sr.id=n.review_id where n.review_id=eid and sr.client_id=c;return jsonb_build_object('kind',kind,'reviewId',r.review_id,'note',r.note);
 elsif kind='guidance' then select * into r from concierge.review_guidance_outputs where review_guidance_outputs.id=eid and client_id=c;return jsonb_build_object('kind',kind,'guidance',jsonb_build_object('record',jsonb_build_object('kind',r.kind,'id',r.id),'body',r.body,'publishedBy',r.publisher->'actorId','publishedAt',concierge.care_instant(r.recorded_at),'originalStart',r.original_start));
 elsif kind='review_attention' then
  select ev.id event_id,ev.recorded_at event_at,ev.resolved_by,a.*,o.body->'publication' publication,am_data.report_id,am_data.report_kind into r from concierge.review_attention_events ev join concierge.review_attention a on a.id=ev.attention_id join concierge.review_guidance_outputs o on o.id=a.prior_review_id join concierge.review_report_amendments am_data on am_data.id=a.amendment_id where ev.id=eid and a.client_id=c and o.client_id=c and o.kind='review';
  return jsonb_build_object('kind',kind,'eventId',r.event_id,'publication',r.publication,'amendmentId',r.amendment_id,'event',jsonb_build_object('kind',r.report_kind,'id',r.report_id),'attention',jsonb_build_object('id',r.id,'priorReview',jsonb_build_object('kind','review','id',r.prior_review_id),'state',case when r.resolved_by is null then 'unresolved' else 'resolved' end,'resolvedBy',case when r.resolved_by is null then null else jsonb_build_object('kind','review','id',r.resolved_by) end),'recordedAt',concierge.care_instant(r.event_at));
 elsif kind='care' then select * into e from concierge.care_events where care_events.id=eid and client_id=c;body:=case when e.kind='use' then concierge.care_use_event(e) when e.kind='reported_product' then e.payload||jsonb_build_object('initialUse',concierge.care_use_event(e)) else e.payload end;return case when e.kind='amendment' then jsonb_build_object('kind','amendment','amendment',body) else jsonb_build_object('kind',e.kind,'event',body) end;
 elsif kind='publication' then select version,published_at,published_by into r from concierge.publications where client_id=c and publications.published_by is not null and concierge.review_cursor_key('publication',client_id::text||':'||version::text)=eid;return jsonb_build_object('kind','publication','publication',concierge.care_publication_ref(c,r.version),'publishedAt',concierge.care_instant(r.published_at),'recordedBy',r.published_by);
 elsif kind='legacy_review' then select * into r from concierge.service_reviews where id=eid and client_id=c;return jsonb_build_object('kind',kind,'publication',null,'review',jsonb_build_object('id',r.id,'channel',r.data->'channel','occurredOn',r.data->'occurredOn','summary',r.data->'summary','reportedUse',r.data->'reportedUse','decision',r.data->'decision','nextReviewOn',r.data->'nextReviewOn','authorId',r.actor_id,'authorLabel','Review with your advisor','recordedAt',concierge.care_instant(r.recorded_at)));
 elsif kind='legacy_instruction' then return (select jsonb_build_object('kind',kind,'revision',concierge.review_legacy_instruction_json(d,p)) from concierge.instruction_publications p join concierge.instruction_drafts d on d.id=p.draft_id where p.id=eid and p.client_id=c);
 elsif kind='legacy_reply' then select * into r from concierge.checkin_replies where id=eid and client_id=c;return jsonb_build_object('kind',kind,'id',r.id,'report',jsonb_build_object('kind',case when (select report_format from concierge.checkin_reports where id=r.report_id)='goal' then 'goal_report' else 'legacy_report' end,'id',r.report_id),'reply',r.reply,'recordedBy',r.created_by,'recordedAt',concierge.care_instant(r.created_at),'publication',null);
 end if;perform concierge.fail('not_found');return null;
end $$;
create function concierge.review_history_page(c uuid,advisor boolean,v integer,token text,lim integer) returns jsonb language plpgsql set search_path='' as $$
declare heads jsonb;fingerprint text;last_id uuid;last_at timestamptz;last_kind text;r record;items jsonb:='[]';item jsonb;next_token text;result jsonb;begin
 heads:=jsonb_build_object('useHead',concierge.care_revision(c),'reportHead',concierge.review_report_revision(c),'instructionHead',concierge.review_instruction_revision(c),'serviceRevision',coalesce((select revision from concierge.service_heads where client_id=c),0),'publicationVersion',(select nullif(published_version,0) from concierge.cases where client_id=c));
 fingerprint:=concierge.plan_hash(jsonb_build_array(c,advisor,v,heads,case when advisor then jsonb_build_array((select max(sequence) from concierge.review_private_notes where client_id=c),(select max(created_at) from concierge.checkin_notes where client_id=c),(select concierge.plan_hash(coalesce(jsonb_agg(jsonb_build_array(n.review_id,n.note,sr.recorded_at) order by sr.recorded_at,n.review_id),'[]')) from concierge.service_review_private n join concierge.service_reviews sr on sr.id=n.review_id where sr.client_id=c)) end));
 if token is not null then if token !~ '^r:[a-f0-9]{64}:[0-9a-f-]{36}$' or split_part(token,':',2)<>fingerprint then perform concierge.fail('cursor_conflict');end if;last_id:=split_part(token,':',3)::uuid;end if;
 for r in select * from (
  select id,submitted_at at,'report'::text kind,case when report_format='goal' then (select (body->'publication'->>'version')::integer from concierge.review_goal_reports where report_id=x.id) end version from concierge.checkin_reports x where client_id=c
  union all select a.id,a.recorded_at,'report_amendment',case when a.report_kind='goal_report' then (select (body->'publication'->>'version')::integer from concierge.review_goal_reports where report_id=a.report_id) end from concierge.review_report_amendments a where client_id=c
  union all select id,recorded_at,'conversation',(body->'publication'->>'version')::integer from concierge.review_conversations where client_id=c and advisor
  union all select id,recorded_at,'private_note',null from concierge.review_private_notes where client_id=c and advisor
  union all select id,created_at,'private_note',null from concierge.checkin_notes where client_id=c and advisor
  -- The parent review time is an internal ordering anchor, never claimed as the note time.
  union all select sr.id,sr.recorded_at,'legacy_review_note',null from concierge.service_review_private n join concierge.service_reviews sr on sr.id=n.review_id where sr.client_id=c and advisor
  union all select id,recorded_at,'guidance',(body->'publication'->>'version')::integer from concierge.review_guidance_outputs o where client_id=c and concierge.review_is_published(o)
  union all select id,recorded_at,'legacy_review',null from concierge.service_reviews s where client_id=c and not exists(select 1 from concierge.review_guidance_outputs o where o.id=s.id and o.kind='review' and o.client_id=s.client_id and o.body=s.data and concierge.review_is_published(o))
  union all select p.id,p.created_at,'legacy_instruction',(d.data->>'planVersion')::integer from concierge.instruction_publications p join concierge.instruction_drafts d on d.id=p.draft_id where p.client_id=c and not exists(select 1 from concierge.review_guidance_outputs o where o.id=p.id and o.kind='instruction' and o.client_id=p.client_id and o.draft_id=p.draft_id and o.output_version=p.version and concierge.review_is_published(o))
  union all select id,created_at,'legacy_reply',null from concierge.checkin_replies reply_row where client_id=c and not exists(select 1 from concierge.review_guidance_outputs o where o.id=reply_row.id and o.kind='reply' and o.client_id=reply_row.client_id and o.body->>'reply'=reply_row.reply and concierge.review_is_published(o))
  union all select ev.id,ev.recorded_at,'review_attention',a.publication_version from concierge.review_attention_events ev join concierge.review_attention a on a.id=ev.attention_id where a.client_id=c
  union all select id,recorded_at,'care',case when kind='amendment' then (payload->'replacement'->'product'->'publication'->>'version')::integer else (payload->'sourcePublication'->>'version')::integer end from concierge.care_events where client_id=c
  union all select concierge.review_cursor_key('publication',client_id::text||':'||version::text),published_at,'publication',version from concierge.publications p where client_id=c and (advisor or exists(select 1 from concierge.entitled_publications where client_id=c and version=p.version))
 ) all_events where (v is null or version=v) order by at,id,kind loop
  if last_id is not null then if concierge.review_cursor_key(r.kind,r.id::text)=last_id then last_id:=null;end if;continue;end if;
  item:=concierge.review_history_item(c,r.kind,r.id);next_token:='r:'||fingerprint||':'||concierge.review_cursor_key(r.kind,r.id::text)::text;
  result:=jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'version',v,'heads',heads,'entries',items||jsonb_build_array(item),'nextCursor',next_token)||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;
  if jsonb_array_length(items)>=lim or concierge.review_bytes(result)>400000 then if jsonb_array_length(items)=0 then perform concierge.fail('invalid_input');end if;return jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'version',v,'heads',heads,'entries',items,'nextCursor',token)||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;end if;
  items:=items||jsonb_build_array(item);token:=next_token;
 end loop;
 if last_id is not null then perform concierge.fail('cursor_conflict');end if;
 return jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'version',v,'heads',heads,'entries',items,'nextCursor',null)||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;
end $$;
create function public.concierge_review_command_v1(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare cmd jsonb:=concierge.review_parse(p_command,'review');a text:=cmd->>'action';c uuid;u uuid:=auth.uid();advisor boolean:=cmd?'clientId';writing boolean;req uuid;old concierge.review_requests;rr bigint;id uuid;at_time timestamptz;event uuid;body jsonb;result jsonb;original jsonb;prior uuid;pub integer;locs jsonb;r record;begin
 if u is null then perform concierge.fail('session_ended');end if;
 writing:=a not in ('request_status_v1','read_care_history_v1','read_advisor_care_history_v1','read_client_plan_v3','read_advisor_publication_v3','read_advisor_reported_products_v1','read_client_instruction_manifest_v1','read_advisor_instruction_manifest_v1','read_client_instruction_v1','read_advisor_instruction_v1');
 if a='request_status_v1' then
  perform concierge.plan_session(u,(auth.jwt()->>'session_id')::uuid);if exists(select 1 from concierge.plan_principals where actor_id=u and kind='agent') then perform concierge.fail('forbidden');end if;
  select * into old from concierge.review_requests where actor_id=u and request_id=(cmd->>'requestId')::uuid and family='review';
  if not found then if exists(select 1 from concierge.plan_principals where actor_id=u and kind in ('owner','human')) then perform concierge.plan_guard();else perform concierge.review_guard(u,false,false);end if;return jsonb_build_object('status','absent');end if;
  perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||old.client_id::text,0));perform concierge.review_request_authorize(old);return jsonb_build_object('status','committed','receipt',old.result);
 end if;
 c:=case when advisor then (cmd->>'clientId')::uuid else u end;
 perform concierge.review_guard(c,advisor,false,a='read_advisor_care_history_v1');
 req:=(cmd->>'requestId')::uuid;if req is not null then perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||u::text||':'||req::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||c::text,0));perform concierge.review_guard(c,advisor,false,a='read_advisor_care_history_v1');
 if req is not null then select * into old from concierge.review_requests where actor_id=u and request_id=req;if found then if old.family<>'review' or old.command is distinct from cmd then perform concierge.fail('request_conflict');end if;perform concierge.review_request_authorize(old);return old.result;end if;end if;
 perform concierge.review_guard(c,advisor,writing,a='read_advisor_care_history_v1');
 at_time:=clock_timestamp();
 if a in ('read_care_history_v1','read_advisor_care_history_v1') then result:=concierge.review_history_page(c,advisor,(cmd->>'version')::integer,cmd->>'cursor',(cmd->>'limit')::integer);
 elsif a in ('read_client_plan_v3','read_advisor_publication_v3') then result:=concierge.review_plan_v3(c,(cmd->>'version')::integer,advisor);
 elsif a='read_advisor_reported_products_v1' then
  rr:=concierge.care_revision(c);if rr<>(cmd->>'expectedUseRevision')::bigint then perform concierge.fail('revision_conflict');end if;
  pub:=(cmd->>'publicationVersion')::integer;if pub is null then select max(ep.version) into pub from concierge.entitled_publications ep where ep.client_id=c;end if;
  if pub is not null and not exists(select 1 from concierge.entitled_publications where client_id=c and version=pub) then perform concierge.fail('not_found');end if;
  result:=concierge.care_reported_page(c,pub,cmd->>'cursor',(cmd->>'limit')::integer,rr);
 elsif a in ('read_client_instruction_manifest_v1','read_advisor_instruction_manifest_v1') then result:=concierge.review_manifest_page(c,cmd->'snapshot',advisor,cmd->>'cursor',(cmd->>'limit')::integer);
 elsif a in ('read_client_instruction_v1','read_advisor_instruction_v1') then result:=concierge.review_instruction_detail(c,cmd->'snapshot',advisor,(cmd->>'instructionId')::uuid,(cmd->>'version')::bigint,cmd->>'contentHash');
 elsif a='record_decision_v2' then
  if cmd->'snapshot'->'publication' is distinct from cmd->'snapshot'->'currentPublication' or (cmd->>'publicationVersion')::integer<>(cmd->'snapshot'->'publication'->>'version')::integer or (cmd->>'expectedDecisionRevision')::bigint<>(cmd->'snapshot'->>'decisionRevision')::bigint then perform concierge.fail('guidance_conflict');end if;
  perform concierge.review_require_publication(c,cmd->'snapshot'->'publication',true);perform concierge.review_snapshot_current(c,cmd->'snapshot');
  body:=concierge.review_document(c,cmd->'snapshot'->'publication');if not exists(select 1 from jsonb_array_elements(body->'content'->'decisions') x where x->'id'=cmd->'decisionId') then perform concierge.fail('not_found');end if;
  insert into concierge.plan_decision_heads values(c,0) on conflict do nothing;select revision into rr from concierge.plan_decision_heads where client_id=c for update;if rr<>(cmd->>'expectedDecisionRevision')::bigint then perform concierge.fail('revision_conflict');end if;
  insert into concierge.plan_decisions(client_id,version,decision_id,choice,reason,actor_id,recorded_at) values(c,(cmd->>'publicationVersion')::integer,cmd->>'decisionId',cmd->>'choice',cmd->>'reason',u,at_time) on conflict(client_id,version,decision_id) do update set choice=excluded.choice,reason=excluded.reason,actor_id=excluded.actor_id,recorded_at=excluded.recorded_at;
  update concierge.plan_decision_heads set revision=revision+1 where client_id=c returning revision into rr;
  result:=jsonb_build_object('requestId',req,'action',a,'snapshot',cmd->'snapshot','decisionRevision',rr,'publicationVersion',cmd->'publicationVersion','decisionId',cmd->'decisionId','choice',cmd->'choice','reason',cmd->'reason');perform concierge.review_capture_decision(c,result,u,req,'review_v2');
 elsif a in ('submit_goal_report_v1','record_conversation_v1','amend_report_v1') then
  rr:=concierge.review_report_revision(c);if rr<>(cmd->>'expectedReportRevision')::bigint then perform concierge.fail('revision_conflict');end if;
  if a='submit_goal_report_v1' then
   body:=cmd->'body';perform concierge.review_goal_check(c,body);perform concierge.care_occurrence(cmd->'occurredOn');
   if not concierge.review_has_observation(body) then result:=jsonb_build_object('requestId',req,'action',a,'outcome','no_op','reason','no_observation','revision',rr,'event',null,'amendmentId',null,'notificationEventId',null,'attentionEventId',null);
   else id:=gen_random_uuid();insert into concierge.review_goal_reports values(id,c,body,cmd->'occurredOn',at_time,u);insert into concierge.checkin_reports(id,client_id,comfort,consistency,changes,submitted_at,report_format) values(id,c,null,null,null,at_time,'goal');insert into concierge.report_photos select (value#>>'{}')::uuid,id from jsonb_array_elements(body->'photoIds');pub:=(body->'publication'->>'version')::integer;end if;
  elsif a='record_conversation_v1' then
   body:=cmd->'body';perform concierge.review_conversation_check(c,body);id:=gen_random_uuid();insert into concierge.review_conversations values(id,c,body,u,at_time);pub:=(body->'publication'->>'version')::integer;
  else
   original:=concierge.review_report_event(c,(cmd->'event'->>'id')::uuid);if original->'kind' is distinct from cmd->'event'->'kind' or cmd->'replacement'->'kind' is distinct from original->'kind' then perform concierge.fail('invalid_input');end if;
   select x.id into prior from concierge.review_report_amendments x where x.report_id=(cmd->'event'->>'id')::uuid and not exists(select 1 from concierge.review_report_amendments y where y.previous_id=x.id);
   if to_jsonb(prior) is distinct from nullif(cmd->'expectedAmendmentHeadId','null'::jsonb) then perform concierge.fail('revision_conflict');end if;
   body:=cmd->'replacement'->'body';perform concierge.care_occurrence(cmd->'occurredOn');
   if original->>'kind'='goal_report' then perform concierge.review_goal_check(c,body,(cmd->'event'->>'id')::uuid);pub:=(original->'body'->'publication'->>'version')::integer;
   else perform concierge.plan_shape(body,concierge.review_shapes()->'legacy');perform concierge.review_photos(c,body->'photoIds',(cmd->'event'->>'id')::uuid);pub:=(concierge.review_current_ref(c)->>'version')::integer;end if;
   id:=gen_random_uuid();insert into concierge.review_report_amendments values(id,c,(cmd->'event'->>'id')::uuid,original->>'kind',prior,cmd,u,at_time);
   insert into concierge.review_amendment_photos select id,(value#>>'{}')::uuid from jsonb_array_elements(body->'photoIds');
   for r in select o.* from concierge.review_guidance_outputs o where o.client_id=c and o.kind='review' and concierge.review_is_published(o) and exists(select 1 from jsonb_array_elements(o.basis->'references') refs where refs->'event'=cmd->'event') loop
    event:=gen_random_uuid();insert into concierge.review_attention values(event,c,id,r.id,(r.body->'publication'->>'version')::integer,at_time);insert into concierge.review_attention_events values(gen_random_uuid(),event,null,at_time);
   end loop;
  end if;
  if id is not null then
   if a='submit_goal_report_v1' then rr:=concierge.review_report_revision(c);
   else insert into concierge.care_report_heads values(c,0) on conflict do nothing;update concierge.care_report_heads set revision=revision+1 where client_id=c returning revision into rr;end if;
   event:=concierge.review_notify(c,id,pub,rr,case a when 'submit_goal_report_v1' then 'goal_reported' when 'record_conversation_v1' then 'conversation_recorded' else 'report_amended' end);
   result:=jsonb_build_object('requestId',req,'action',a,'event',case when a='amend_report_v1' then cmd->'event' else jsonb_build_object('kind',case when a='submit_goal_report_v1' then 'goal_report' else 'conversation' end,'id',id) end,'amendmentId',case when a='amend_report_v1' then id end,'revision',rr,'recordedAt',concierge.care_instant(at_time),'notificationEventId',event,'attentionEventId',event);
  end if;
 elsif a='append_private_review_note_v1' then
  perform concierge.review_note_subject(c,cmd->'reviewEvent');id:=gen_random_uuid();insert into concierge.review_private_notes(id,client_id,subject,note,recorded_by,recorded_at) values(id,c,cmd->'reviewEvent',cmd->>'note',u,at_time);
  result:=jsonb_build_object('requestId',req,'action',a,'noteId',id,'reviewEvent',cmd->'reviewEvent','recordedBy',u,'recordedAt',concierge.care_instant(at_time),'notificationEventId',null);
 else perform concierge.fail('invalid_input');end if;
 perform concierge.review_guard(c,advisor,writing,a='read_advisor_care_history_v1');
 if a='record_decision_v2' and cmd->'snapshot'->>'asOfDay'<>to_char((clock_timestamp() at time zone 'America/Chicago')::date,'YYYY-MM-DD') then perform concierge.fail('guidance_conflict');end if;
 if req is not null then insert into concierge.review_requests(actor_id,request_id,client_id,family,command,result) values(u,req,c,'review',cmd,result);end if;
 return result;
end $$;

create function concierge.review_scope_check(c uuid,b jsonb) returns jsonb language plpgsql set search_path='' as $$declare doc jsonb;state jsonb;begin
 perform concierge.review_require_publication(c,b->'publication');doc:=concierge.review_document(c,b->'publication');
 if b->'productId'='null'::jsonb then
  if not exists(select 1 from jsonb_array_elements(doc->'content'->'routine') s where s->>'kind'='instruction' and s->'slotId'=b->'slotId' and s->'productId'='null'::jsonb) or b->'useBasis'<>'null'::jsonb then perform concierge.fail('not_found');end if;return null;
 end if;
 perform concierge.care_resolve_product(c,jsonb_build_object('kind','plan_product','publication',b->'publication','slotId',b->'slotId','productId',b->'productId'));
 state:=concierge.care_effective_use(c,jsonb_build_object('kind','plan_product','publication',b->'publication','slotId',null,'productId',b->'productId'));
 return state;
end $$;
create function concierge.review_instruction_use(c uuid,b jsonb) returns jsonb language plpgsql set search_path='' as $$declare s jsonb;begin
 s:=concierge.review_scope_check(c,b);if s is null then return 'null'::jsonb;end if;
 return jsonb_build_object('useRevision',concierge.care_revision(c),'latestEventId',s->'latestEvent'->'eventId','amendmentHeadId',s->'latestEvent'->'amendment'->'id');
end $$;
create function concierge.review_input_refs(b jsonb) returns jsonb language sql immutable set search_path='' as $$
 select case b->>'kind' when 'review' then b->'reportRefs' when 'reply' then jsonb_build_array(b->'reportRef') else '[]'::jsonb end
$$;
-- Complete private relation from the actual closed immutable inputs, never an inline sample.
create function concierge.review_source_location_canonical(l jsonb) returns jsonb language plpgsql immutable set search_path='' as $$declare p jsonb:=l->'locator';k text;begin
 for k in select jsonb_object_keys(p) loop if k<>'kind' then p:=jsonb_set(p,array[k],to_jsonb((p->>k)::bigint));end if;end loop;
 return jsonb_build_object('sourceId',(l->>'sourceId')::uuid,'sourceVersion',(l->>'sourceVersion')::bigint,'locator',p);
end $$;
create function concierge.review_guidance_source_locations(c uuid,b jsonb) returns setof jsonb language sql set search_path='' as $$
 select concierge.review_source_location_canonical(loc) from jsonb_array_elements(concierge.review_input_refs(b)) ref
 join concierge.review_conversations cv on ref->>'kind'='conversation' and cv.id=(ref->>'id')::uuid and cv.client_id=c
 cross join lateral jsonb_array_elements((cv.body->'clientReported')||(cv.body->'advisorConclusions')||(cv.body->'agentProposals')) f
 cross join lateral jsonb_array_elements(f->'sources') loc
$$;
create function concierge.review_guidance_sources_check(c uuid,b jsonb,actor uuid default auth.uid()) returns void language plpgsql set search_path='' as $$declare l jsonb;begin
 -- Grants are source/version scoped. Each representative is a real exact original locator;
 -- all locators remain in the immutable input and complete manifest relation.
 for l in select distinct on(value->>'sourceId',value->>'sourceVersion') value from concierge.review_guidance_source_locations(c,b) value order by value->>'sourceId',value->>'sourceVersion',concierge.review_compact(value) collate "C" loop
  perform concierge.review_source_check(c,jsonb_build_array(l),actor);
 end loop;
 if not concierge.plan_read_human_live(actor) then perform concierge.fail('forbidden');end if;
 if actor=auth.uid() then perform concierge.plan_session(actor,(auth.jwt()->>'session_id')::uuid);end if;
end $$;
create function concierge.review_guidance_source_manifest(c uuid,b jsonb,inputs jsonb) returns jsonb language plpgsql set search_path='' as $$declare n bigint;locator_digest text;ordered_inputs jsonb;begin
 select count(*),encode(sha256(coalesce(string_agg(sha256(convert_to(concierge.review_compact(loc),'UTF8')),''::bytea order by concierge.review_compact(loc) collate "C"),''::bytea)),'hex') into n,locator_digest from (select distinct value loc from concierge.review_guidance_source_locations(c,b) value) distinct_locations;
 if n>(concierge.review_command_fields()->'record_conversation_v1'->'body'->'fields'->'clientReported'->>'max')::bigint*(concierge.review_command_fields()->'record_conversation_v1'->'body'->'fields'->'clientReported'->'item'->'fields'->'sources'->>'max')::bigint*(concierge.guidance_command_fields()->'create_guidance_draft_v1'->'body'->'variants'->0->'fields'->'reportRefs'->>'max')::bigint then perform concierge.fail('invalid_input');end if;
 select coalesce(jsonb_agg(value order by value->'event'->>'kind',value->'event'->>'id'),'[]') into ordered_inputs from jsonb_array_elements(inputs) value;
 return jsonb_build_object('schemaVersion',1,'hash',concierge.plan_hash(jsonb_build_object('schemaVersion',1,'inputs',ordered_inputs,'locatorDigest',locator_digest,'count',n)),'count',n);
end $$;

create function concierge.review_guidance_basis(c uuid,b jsonb) returns jsonb language plpgsql set search_path='' as $$
declare basis jsonb:=concierge.plan_dependency_basis_v2(c);refs jsonb:=concierge.review_input_refs(b);captured_refs jsonb:='[]';inputs jsonb:='[]';ref jsonb;original jsonb;head uuid;input_hash text;amendment_hash text;conv concierge.review_conversations;use_basis jsonb;begin
 perform concierge.review_require_publication(c,b->'publication');
 if b->>'kind'='instruction' then use_basis:=concierge.review_instruction_use(c,b);if use_basis->'latestEventId'<>'null'::jsonb then refs:=jsonb_build_array(jsonb_build_object('kind','use','id',use_basis->'latestEventId'));end if;end if;
 if (select count(distinct value) from jsonb_array_elements(refs))<>jsonb_array_length(refs) then perform concierge.fail('invalid_input');end if;
 for ref in select value from jsonb_array_elements(refs) loop
  head:=null;amendment_hash:=null;
  if ref->>'kind' in ('goal_report','legacy_report') then
   original:=concierge.review_report_event(c,(ref->>'id')::uuid);if original->'kind' is distinct from ref->'kind' then perform concierge.fail('not_found');end if;
   input_hash:=concierge.plan_hash(original);select a.id,concierge.plan_hash(a.body) into head,amendment_hash from concierge.review_report_amendments a where a.client_id=c and a.report_id=(ref->>'id')::uuid and not exists(select 1 from concierge.review_report_amendments x where x.previous_id=a.id);
  elsif ref->>'kind'='conversation' then
   select * into conv from concierge.review_conversations where id=(ref->>'id')::uuid and client_id=c;if not found then perform concierge.fail('not_found');end if;input_hash:=concierge.plan_hash(conv.body);
  else
   if not exists(select 1 from concierge.care_events e where e.client_id=c and e.id=(ref->>'id')::uuid and (e.kind=ref->>'kind' or b->>'kind'='instruction' and e.kind='reported_product')) then perform concierge.fail('not_found');end if;
   select concierge.plan_hash(jsonb_build_object('kind',e.kind,'product',e.product,'payload',e.payload)) into input_hash from concierge.care_events e where e.id=(ref->>'id')::uuid and e.client_id=c;select a.id,concierge.plan_hash(a.body) into head,amendment_hash from concierge.care_use_amendments a where a.event_id=(ref->>'id')::uuid and not exists(select 1 from concierge.care_use_amendments x where x.previous_id=a.id);
  end if;
  captured_refs:=captured_refs||jsonb_build_array(jsonb_build_object('event',ref,'amendmentHeadId',head));
  inputs:=inputs||jsonb_build_array(jsonb_build_object('event',ref,'contentHash',input_hash,'amendmentHeadId',head,'amendmentContentHash',amendment_hash));
 end loop;
 perform concierge.review_guidance_sources_check(c,b);
 return (basis-'schemaVersion'-'references')||jsonb_build_object('schemaVersion',1,'publication',b->'publication','references',captured_refs,'sourceManifest',concierge.review_guidance_source_manifest(c,b,inputs));
end $$;
create function concierge.review_guidance_issues(c uuid,b jsonb,captured jsonb,current_basis jsonb,reviewed boolean) returns jsonb language plpgsql set search_path='' as $$declare r jsonb:='[]';k text;s jsonb;begin
 if captured is distinct from current_basis or b->'publication' is distinct from concierge.review_current_ref(c) then r:=r||jsonb_build_array(jsonb_build_object('path','basis','code','basis_conflict'));end if;
 if b->>'kind'='review' then foreach k in array array['clientReport','conclusion','rationale','nextStep'] loop if concierge.trim_text(b->>k)='' then r:=r||jsonb_build_array(jsonb_build_object('path','body.'||k,'code','required'));end if;end loop;
 elsif b->>'kind'='reply' then if concierge.trim_text(b->>'reply')='' then r:=r||jsonb_build_array(jsonb_build_object('path','body.reply','code','required'));end if;
 else
  if jsonb_array_length(b->'directions')=0 or exists(select 1 from jsonb_array_elements_text(b->'directions') x where concierge.trim_text(x)='') then r:=r||jsonb_build_array(jsonb_build_object('path','body.directions','code','required'));end if;
  if concierge.trim_text(b->>'reason')='' then r:=r||jsonb_build_array(jsonb_build_object('path','body.reason','code','required'));end if;
  s:=b->'schedule';if jsonb_array_length(s->'periods')=0 or s->'days'->>'kind'='selected' and jsonb_array_length(s->'days'->'weekdays')=0 or exists(select 1 from jsonb_array_elements(s->'stages') x where concierge.trim_text(x->>'directions')='' or concierge.trim_text(x->>'proceedOnlyWhen')='') then r:=r||jsonb_build_array(jsonb_build_object('path','body.schedule','code','required'));end if;
  s:=concierge.review_scope_check(c,b);if s is not null and coalesce((s->>'contradiction')::boolean,false) then r:=r||jsonb_build_array(jsonb_build_object('path','body','code','unresolved_reference'));end if;
 end if;
 if not reviewed then r:=r||jsonb_build_array(jsonb_build_object('path','review','code','review_required'));end if;return r;
end $$;
create function concierge.review_guidance_target(d uuid,c uuid,k text,n bigint,b jsonb,basis jsonb) returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('draftId',d,'clientId',c,'kind',k,'revision',n,'contentHash',concierge.plan_hash(b),'basisHash',concierge.plan_hash(basis))$$;
create function concierge.review_guidance_review_json(r concierge.review_guidance_reviews) returns jsonb language sql set search_path='' as $$select jsonb_build_object('id',r.id,'target',r.target,'reviewedBy',r.actor_id,'reviewedAt',concierge.care_instant(r.recorded_at))$$;
create function concierge.review_guidance_approval_json(a concierge.review_guidance_approvals) returns jsonb language sql set search_path='' as $$select jsonb_build_object('id',a.id,'target',a.target,'scope',a.scope,'publisher',a.publisher,'approvedBy',a.approved_by,'approvedAt',concierge.care_instant(a.approved_at),'policyRevision',a.policy_revision,'revokedAt',(select concierge.care_instant(recorded_at) from concierge.review_guidance_revocations where approval_id=a.id),'receiptId',(select receipt_id from concierge.review_guidance_outputs where approval_id=a.id))$$;
create function concierge.review_guidance_publisher(c uuid,p jsonb,body jsonb) returns void language plpgsql set search_path='' as $$declare actor uuid:=(p->>'actorId')::uuid;begin
 if p->>'kind'<>'human' or not concierge.plan_read_human_live(actor) then perform concierge.fail('forbidden');end if;
 perform 1 from concierge.advisors where user_id=actor and active and can_publish for share;if not found then perform concierge.fail('forbidden');end if;
 perform concierge.review_guidance_sources_check(c,body,actor);
end $$;
create function concierge.review_guidance_draft_view(d concierge.review_guidance_drafts) returns jsonb language plpgsql set search_path='' as $$
declare r concierge.review_guidance_revisions;cur jsonb;review concierge.review_guidance_reviews;approval concierge.review_guidance_approvals;pol concierge.plan_policy;rv jsonb;ap jsonb;begin
 select * into r from concierge.review_guidance_revisions where draft_id=d.id and revision=d.revision;cur:=concierge.review_guidance_basis(d.client_id,r.body);select * into pol from concierge.plan_policy where singleton;
 if r.basis=cur then select * into review from concierge.review_guidance_reviews x where x.draft_id=d.id and x.revision=d.revision and x.target=r.target and concierge.plan_read_human_live(x.actor_id) order by recorded_at desc,id desc limit 1;end if;
 if review.id is not null then
  select * into approval from concierge.review_guidance_approvals a where a.draft_id=d.id and a.revision=d.revision and a.target=r.target and a.policy_revision=pol.revision and (not pol.require_kanuj_approval or a.approved_by=pol.owner_actor_id) and concierge.plan_read_human_live(a.approved_by) and not exists(select 1 from concierge.review_guidance_revocations where approval_id=a.id) and not exists(select 1 from concierge.review_guidance_outputs where approval_id=a.id) order by approved_at desc,id desc limit 1;
  if approval.id is not null then begin perform concierge.review_guidance_publisher(d.client_id,approval.publisher,r.body);ap:=concierge.review_guidance_approval_json(approval);exception when raise_exception then ap:=null;end;end if;
 end if;
 if review.id is not null then rv:=concierge.review_guidance_review_json(review);end if;
 return jsonb_build_object('target',r.target,'body',r.body,'capturedBasis',r.basis,'currentBasis',cur,'needsRebase',r.basis is distinct from cur,'savedAt',concierge.care_instant(r.recorded_at),'recordedBy',r.actor_id,'review',rv,'approval',ap,'issues',concierge.review_guidance_issues(d.client_id,r.body,r.basis,cur,review.id is not null));
end $$;
create function concierge.review_guidance_body_check(c uuid,b jsonb) returns void language plpgsql set search_path='' as $$declare use_basis jsonb;begin
 perform concierge.plan_shape(b,concierge.review_shapes()->'body');if concierge.review_bytes(b)>120000 then perform concierge.fail('invalid_input');end if;
 if b->>'kind'='review' then perform concierge.care_occurrence(b->'occurredOn');
 elsif b->>'kind'='instruction' then
  if (b->'baseInstructionId'='null'::jsonb) is distinct from ((b->>'baseInstructionVersion')::bigint=0) or (b->'productId'='null'::jsonb) is distinct from (b->'useBasis'='null'::jsonb) then perform concierge.fail('invalid_input');end if;
  use_basis:=concierge.review_instruction_use(c,b);if b->'useBasis' is distinct from use_basis then perform concierge.fail('basis_conflict');end if;
 end if;
end $$;
create function public.concierge_guidance_command_v1(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare cmd jsonb:=concierge.review_parse(p_command,'guidance');a text:=cmd->>'action';pr concierge.plan_principals;pol concierge.plan_policy;c uuid;d concierge.review_guidance_drafts;r concierge.review_guidance_revisions;old concierge.review_requests;req uuid;body jsonb;basis jsonb;current_basis jsonb;target jsonb;result jsonb;approval concierge.review_guidance_approvals;at_time timestamptz;id uuid;writing boolean:=a not in ('read_guidance_draft_v1','request_status_v1');begin
 pr:=concierge.plan_guard();if pr.kind='agent' then perform concierge.fail('forbidden');end if;select * into pol from concierge.plan_policy where singleton;
 if a='request_status_v1' then
  select * into old from concierge.review_requests where actor_id=auth.uid() and request_id=(cmd->>'requestId')::uuid and family='guidance';if not found then return jsonb_build_object('status','absent');end if;
  perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||old.client_id::text,0));perform concierge.review_request_authorize(old);return jsonb_build_object('status','committed','receipt',old.result);
 end if;
 if a='create_guidance_draft_v1' then c:=(cmd->>'clientId')::uuid;
 elsif a='revoke_guidance_approval_v1' then select * into approval from concierge.review_guidance_approvals where review_guidance_approvals.id=(cmd->>'approvalId')::uuid;if not found then perform concierge.fail('not_found');end if;select * into d from concierge.review_guidance_drafts where review_guidance_drafts.id=approval.draft_id;c:=d.client_id;
 else select * into d from concierge.review_guidance_drafts where review_guidance_drafts.id=coalesce((cmd->>'draftId')::uuid,(cmd->'target'->>'draftId')::uuid);if not found then perform concierge.fail('not_found');end if;c:=d.client_id;end if;
 perform concierge.review_guard(c,true,writing,true);req:=(cmd->>'requestId')::uuid;
 if req is not null then perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||auth.uid()::text||':'||req::text,0));end if;
 perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||c::text,0));perform concierge.review_guard(c,true,writing,true);
 if req is not null then select * into old from concierge.review_requests where actor_id=auth.uid() and request_id=req;if found then if old.family<>'guidance' or old.command is distinct from cmd then perform concierge.fail('request_conflict');end if;perform concierge.review_request_authorize(old);return old.result;end if;end if;
 at_time:=clock_timestamp();
 if a='create_guidance_draft_v1' then
  body:=cmd->'body';perform concierge.review_guidance_body_check(c,body);basis:=concierge.review_guidance_basis(c,body);id:=gen_random_uuid();target:=concierge.review_guidance_target(id,c,body->>'kind',1,body,basis);
  insert into concierge.review_guidance_drafts values(id,c,body->>'kind',1) returning * into d;insert into concierge.review_guidance_revisions values(id,1,body,basis,target,auth.uid(),at_time);result:=jsonb_build_object('requestId',req,'draft',concierge.review_guidance_draft_view(d));
 else
  select * into d from concierge.review_guidance_drafts where review_guidance_drafts.id=d.id for update;select * into r from concierge.review_guidance_revisions where draft_id=d.id and revision=d.revision;
  if a='read_guidance_draft_v1' then result:=concierge.review_guidance_draft_view(d);
  else
   if a<>'revoke_guidance_approval_v1' and cmd->'target' is distinct from r.target then perform concierge.fail('revision_conflict');end if;
   current_basis:=concierge.review_guidance_basis(c,r.body);
   if a in ('save_guidance_draft_v1','rebase_guidance_draft_v1') then
    if exists(select 1 from concierge.review_guidance_outputs where draft_id=d.id) then perform concierge.fail('guidance_conflict');end if;
    if a='save_guidance_draft_v1' then
     body:=cmd->'body';if body->>'kind'<>d.kind or body->'publication' is distinct from r.body->'publication' then perform concierge.fail('invalid_input');end if;perform concierge.review_guidance_body_check(c,body);
     basis:=r.basis;if body->'reportRefs' is distinct from r.body->'reportRefs' or body->'reportRef' is distinct from r.body->'reportRef' or body->'slotId' is distinct from r.body->'slotId' or body->'productId' is distinct from r.body->'productId' then if r.basis is distinct from current_basis then perform concierge.fail('basis_conflict');end if;basis:=concierge.review_guidance_basis(c,body);end if;
    else
     if current_basis is distinct from cmd->'expectedBasis' then perform concierge.fail('basis_conflict');end if;basis:=current_basis;body:=r.body;
     if d.kind='instruction' then body:=jsonb_set(body,'{useBasis}',concierge.review_instruction_use(c,body));end if;
    end if;
    target:=concierge.review_guidance_target(d.id,c,d.kind,d.revision+1,body,basis);insert into concierge.review_guidance_revisions values(d.id,d.revision+1,body,basis,target,auth.uid(),at_time);update concierge.review_guidance_drafts set revision=revision+1 where review_guidance_drafts.id=d.id returning * into d;result:=jsonb_build_object('requestId',req,'draft',concierge.review_guidance_draft_view(d));
   elsif a='review_guidance_v1' then
    if jsonb_array_length(concierge.review_guidance_issues(c,r.body,r.basis,current_basis,true))>0 then perform concierge.fail('not_ready');end if;
    insert into concierge.review_guidance_reviews values(gen_random_uuid(),d.id,d.revision,r.target,auth.uid(),at_time);result:=jsonb_build_object('requestId',req,'draft',concierge.review_guidance_draft_view(d));
   elsif a='approve_guidance_v1' then
    if cmd->>'scope'<>d.kind||'.publish' or jsonb_array_length(concierge.review_guidance_issues(c,r.body,r.basis,current_basis,exists(select 1 from concierge.review_guidance_reviews rv where rv.draft_id=d.id and rv.revision=d.revision and rv.target=r.target and concierge.plan_read_human_live(rv.actor_id))))>0 then perform concierge.fail('not_ready');end if;
    if pr.kind<>'owner' and (pol.require_kanuj_approval or cmd->'publisher'->>'actorId'<>auth.uid()::text) then perform concierge.fail('forbidden');end if;perform concierge.review_guidance_publisher(c,cmd->'publisher',r.body);
    insert into concierge.review_guidance_approvals values(gen_random_uuid(),d.id,d.revision,r.target,cmd->'publisher',cmd->>'scope',auth.uid(),at_time,pol.revision) returning * into approval;result:=jsonb_build_object('requestId',req,'approval',concierge.review_guidance_approval_json(approval));
   elsif a='revoke_guidance_approval_v1' then
    if (cmd->>'expectedPolicyRevision')::bigint<>pol.revision then perform concierge.fail('revision_conflict');end if;if pr.kind<>'owner' and approval.approved_by<>auth.uid() then perform concierge.fail('forbidden');end if;
    insert into concierge.review_guidance_revocations values(approval.id,auth.uid(),at_time,pol.revision) on conflict do nothing;select recorded_at into at_time from concierge.review_guidance_revocations where approval_id=approval.id;result:=jsonb_build_object('requestId',req,'approvalId',approval.id,'revokedBy',auth.uid(),'revokedAt',concierge.care_instant(at_time),'policyRevision',pol.revision);
   elsif a='publish_guidance_v1' then result:=concierge.review_guidance_publish(d,r,cmd);
   else perform concierge.fail('invalid_input');end if;
  end if;
 end if;
 perform concierge.review_guard(c,true,writing,true);
 if req is not null then insert into concierge.review_requests(actor_id,request_id,client_id,family,command,result) values(auth.uid(),req,c,'guidance',cmd,result);end if;return result;
end $$;

create function concierge.review_instruction_entries(c uuid,p jsonb,day date) returns setof jsonb language plpgsql set search_path='' as $$
declare r record;b jsonb;state jsonb;states jsonb:='{}';doc jsonb;item jsonb;pid text;begin
 doc:=concierge.review_document(c,p);
 for b in select value from jsonb_array_elements(doc->'content'->'products') loop states:=states||jsonb_build_object(b->>'id',concierge.care_effective_use(c,jsonb_build_object('kind','plan_product','publication',p,'productId',b->'id','slotId',null)));end loop;
 for r in select distinct on(slot,product) * from (
  select o.id,o.output_version version,'authored_schedule'::text format,o.body->>'slotId' slot,o.body->>'productId' product,o.body,o.target->>'contentHash' hash,o.recorded_at,o.basis from concierge.review_guidance_outputs o where o.client_id=c and o.kind='instruction' and concierge.review_is_published(o) and o.body->'publication'=p and o.body->>'effectiveOn'<=to_char(day,'YYYY-MM-DD')
  union all select ip.id,ip.version,'legacy_usage',d.data->>'slot',d.data->>'productId',d.data,concierge.plan_hash(d.data),ip.created_at,null from concierge.instruction_publications ip join concierge.instruction_drafts d on d.id=ip.draft_id where ip.client_id=c and (d.data->>'planVersion')::integer=(p->>'version')::integer and p->>'documentSchemaVersion' in ('1','2') and d.data->>'effectiveOn'<=to_char(day,'YYYY-MM-DD') and not exists(select 1 from concierge.review_guidance_outputs linked where linked.id=ip.id and linked.kind='instruction' and linked.client_id=ip.client_id and linked.draft_id=ip.draft_id and linked.output_version=ip.version and concierge.review_is_published(linked))
 ) candidates order by slot,product,version desc,recorded_at desc,id desc loop
  state:=states->r.product;
  item:=jsonb_build_object('instructionId',r.id,'version',r.version,'format',r.format,'scope',jsonb_build_object('publication',p,'slotId',r.slot,'productId',r.product),'contentHash',r.hash,'effectiveOn',r.body->'effectiveOn','baseInstructionId',r.body->'baseInstructionId','baseInstructionVersion',r.body->'baseInstructionVersion','reviewedUseBasis',case when r.format='authored_schedule' then r.body->'useBasis' end,'basisStatus',case when r.format='legacy_usage' then 'legacy_unversioned' when (r.basis->>'useHead')::bigint=concierge.care_revision(c) and (r.basis->>'reportHead')::bigint=concierge.review_report_revision(c) then 'current' else 'changed' end,'originalStart',case when r.product is null then null else coalesce(state->'originalStart',jsonb_build_object('state','unknown')) end);
  if r.format='legacy_usage' then item:=item||jsonb_build_object('baseInstructionVersion',r.version-1,'baseInstructionId',(select prev.id from concierge.instruction_publications prev join concierge.instruction_drafts pd on pd.id=prev.draft_id where prev.client_id=c and prev.version=r.version-1 and pd.data->>'slot'=r.slot and pd.data->>'productId'=r.product and (pd.data->>'planVersion')::integer=(p->>'version')::integer limit 1));end if;
  return next item;
 end loop;return;
end $$;
create function concierge.review_latest_summary(c uuid,p jsonb) returns jsonb language sql set search_path='' as $$
 select jsonb_build_object('reviewId',id,'publicationVersion',(p->>'version')::integer,'publishedAt',concierge.care_instant(recorded_at),'occurredOn',body->'occurredOn','conclusion',body->'conclusion','rationale',body->'rationale','nextStep',body->'nextStep','nextReviewOn',body->'nextReviewOn') from concierge.review_guidance_outputs o where client_id=c and kind='review' and concierge.review_is_published(o) and body->'publication'=p order by recorded_at desc,id desc limit 1
$$;
create function concierge.review_snapshot(c uuid,p jsonb,day date) returns jsonb language plpgsql set search_path='' as $$declare clinical jsonb;instructions jsonb;guidance jsonb;snapshot jsonb;doc jsonb;begin
 doc:=concierge.review_document(c,p);select coalesce(jsonb_agg(value order by value->>'instructionId'),'[]') into instructions from concierge.review_instruction_entries(c,p,day) value;
 select coalesce(jsonb_agg(jsonb_build_array(id,kind,target->'contentHash') order by id),'[]') into guidance from concierge.review_guidance_outputs o where client_id=c and concierge.review_is_published(o) and body->'publication'=p and (kind<>'instruction' or body->>'effectiveOn'<=to_char(day,'YYYY-MM-DD'));
 clinical:=jsonb_build_object('clientId',c,'publication',p,'documentHash',concierge.plan_hash(doc->'content'),'legacyMaterialBasis',concierge.plan_basis(c)-'publicationVersion','useHead',concierge.care_revision(c),'reportHead',concierge.review_report_revision(c),'guidance',guidance,'instructions',instructions);
 snapshot:=jsonb_build_object('publication',p,'currentPublication',concierge.review_current_ref(c),'useHead',concierge.care_revision(c),'reportHead',concierge.review_report_revision(c),'instructionHead',concierge.review_instruction_revision(c),'serviceRevision',coalesce((select revision from concierge.service_heads where client_id=c),0),'decisionRevision',coalesce((select revision from concierge.plan_decision_heads where client_id=c),0),'asOfDay',to_char(day,'YYYY-MM-DD'),'manifestHash',concierge.plan_hash(clinical));return snapshot;
end $$;
create function concierge.review_snapshot_current(c uuid,s jsonb) returns void language plpgsql set search_path='' as $$declare current_s jsonb;begin
 current_s:=concierge.review_snapshot(c,s->'publication',(clock_timestamp() at time zone 'America/Chicago')::date);
 if current_s is distinct from s then perform concierge.fail('guidance_conflict');end if;
end $$;
create function concierge.review_decision_row_hash(p concierge.plan_decisions) returns text language sql immutable set search_path='' as $$select concierge.plan_hash(jsonb_build_object('clientId',p.client_id,'publicationVersion',p.version,'decisionId',p.decision_id,'choice',p.choice,'reason',p.reason,'actorId',p.actor_id,'recordedAt',concierge.care_instant(p.recorded_at)))$$;
create function concierge.review_capture_decision(c uuid,res jsonb,actor uuid,request uuid,family text) returns void language plpgsql set search_path='' as $$declare p concierge.plan_decisions;begin
 select * into p from concierge.plan_decisions where client_id=c and version=(res->>'publicationVersion')::integer and decision_id=res->>'decisionId';
 if not found or p.actor_id<>actor or to_jsonb(p.choice) is distinct from res->'choice' or to_jsonb(p.reason) is distinct from nullif(res->'reason','null'::jsonb) or (res->>'decisionRevision')::bigint<>(select revision from concierge.plan_decision_heads where client_id=c) then perform concierge.fail('request_conflict');end if;
 insert into concierge.review_decision_provenance values(c,p.version,p.decision_id,(res->>'decisionRevision')::bigint,actor,request,family,concierge.review_decision_row_hash(p));
end $$;
create function concierge.review_decision_guidance(c uuid,pub integer,states jsonb,snapshot jsonb) returns jsonb language plpgsql set search_path='' as $$declare state jsonb;r record;p concierge.plan_decisions;proof concierge.review_decision_provenance;accepted jsonb;revision bigint;status text;result_array jsonb:='[]';begin
 for state in select value from jsonb_array_elements(states) loop
  accepted:=null;revision:=null;status:='legacy_unbound';
  select * into r from (
   select actor_id,request_id,'plan_v1'::text family,result from concierge.plan_requests where scope_client_id=c and command->>'action'='record_decision_v1' and (result->>'publicationVersion')::integer=pub and result->'decisionId'=state->'decisionId'
   union all select actor_id,request_id,'review_v2',result from concierge.review_requests where client_id=c and family='review' and command->>'action'='record_decision_v2' and (result->>'publicationVersion')::integer=pub and result->'decisionId'=state->'decisionId'
  ) receipts order by (result->>'decisionRevision')::bigint desc limit 1;
  if found then
   select * into p from concierge.plan_decisions where client_id=c and version=pub and decision_id=state->>'decisionId';
   if found then
    select * into proof from concierge.review_decision_provenance where client_id=c and publication_version=pub and decision_id=p.decision_id and actor_id=r.actor_id and request_id=r.request_id and family=r.family and decision_revision=(r.result->>'decisionRevision')::bigint and row_hash=concierge.review_decision_row_hash(p);
    if found and to_jsonb(p.choice)=state->'choice' and to_jsonb(p.reason) is not distinct from nullif(state->'reason','null'::jsonb) then
     revision:=proof.decision_revision;
     if r.family='review_v2' and r.result->'snapshot'->'publication'=snapshot->'publication' then accepted:=r.result->'snapshot';status:=case when accepted->'manifestHash'=snapshot->'manifestHash' then 'current' else 'stale' end;end if;
    end if;
   end if;
  end if;
  result_array:=result_array||jsonb_build_array(jsonb_build_object('decisionId',state->'decisionId','recordedDecisionRevision',revision,'acceptedSnapshot',accepted,'basisStatus',status));
 end loop;return result_array;
end $$;
create function concierge.review_plan_v3(c uuid,v integer,advisor boolean) returns jsonb language plpgsql set search_path='' as $$declare base jsonb;p jsonb;snapshot jsonb;guidance jsonb;counted integer;day date:=(clock_timestamp() at time zone 'America/Chicago')::date;begin
 base:=concierge.review_care_command_before_v1(jsonb_build_object('schemaVersion',1,'action',case when advisor then 'read_advisor_publication_v2' else 'read_client_plan_v2' end,'version',v)||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end);
 if base->'plan'='null'::jsonb then return base||jsonb_build_object('schemaVersion',3,'currentGuidance',null,'decisionGuidance','[]'::jsonb);end if;
 p:=jsonb_build_object('version',base->'plan'->'version','documentSchemaVersion',base->'plan'->'documentSchemaVersion');snapshot:=concierge.review_snapshot(c,p,day);select count(*) into counted from concierge.review_instruction_entries(c,p,day);
 guidance:=jsonb_build_object('schemaVersion',1,'mode',case when p=snapshot->'currentPublication' then 'current_document' else 'historical_document' end,'instructionSemantics','current_for_selected_publication','snapshot',snapshot,'instructionCount',counted);
 base:=base||jsonb_build_object('schemaVersion',3,'currentGuidance',guidance,'latestPublicReview',concierge.review_latest_summary(c,p),'decisionGuidance',concierge.review_decision_guidance(c,(p->>'version')::integer,base->'decisions',snapshot));
 -- Only the independent reported-products page may be shortened; every plan product remains present.
 while concierge.review_bytes(base)>1800000 and jsonb_array_length(base->'use'->'reportedProducts'->'items')>1 loop
  base:=jsonb_set(base,'{use,reportedProducts}',concierge.care_reported_page(c,(p->>'version')::integer,null,jsonb_array_length(base->'use'->'reportedProducts'->'items')-1,(snapshot->>'useHead')::bigint)-'revision');
 end loop;
 if concierge.review_bytes(base)>1800000 then perform concierge.fail('invalid_input');end if;return base;
end $$;
create function concierge.review_manifest_page(c uuid,s jsonb,advisor boolean,token text,lim integer) returns jsonb language plpgsql set search_path='' as $$declare item jsonb;items jsonb:='[]';last_id uuid;last_seen boolean:=token is null;fingerprint text;next_token text;total integer;result jsonb;begin
 perform concierge.review_snapshot_current(c,s);fingerprint:=concierge.plan_hash(jsonb_build_array(c,advisor,s));
 if token is not null then if token !~ '^r:[a-f0-9]{64}:[0-9a-f-]{36}$' or split_part(token,':',2)<>fingerprint then perform concierge.fail('cursor_conflict');end if;last_id:=split_part(token,':',3)::uuid;end if;
 select count(*) into total from concierge.review_instruction_entries(c,s->'publication',(s->>'asOfDay')::date);if total>2550 then perform concierge.fail('invalid_input');end if;
 for item in select value from concierge.review_instruction_entries(c,s->'publication',(s->>'asOfDay')::date) value order by value->>'instructionId' loop
  if not last_seen then if item->>'instructionId'=last_id::text then last_seen:=true;end if;continue;end if;
  next_token:='r:'||fingerprint||':'||(item->>'instructionId');
  result:=jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'snapshot',s,'total',total,'cursor',token,'items',items||jsonb_build_array(item),'nextCursor',next_token)||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;
  if jsonb_array_length(items)>=lim or concierge.review_bytes(result)>400000 then return jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'snapshot',s,'total',total,'cursor',token,'items',items,'nextCursor','r:'||fingerprint||':'||(items->-1->>'instructionId'))||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;end if;
  items:=items||jsonb_build_array(item);
 end loop;if not last_seen then perform concierge.fail('cursor_conflict');end if;
 return jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'snapshot',s,'total',total,'cursor',token,'items',items,'nextCursor',null)||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;
end $$;
create function concierge.review_instruction_detail(c uuid,s jsonb,advisor boolean,requested uuid,ver bigint,hash text) returns jsonb language plpgsql set search_path='' as $$declare item jsonb;o concierge.review_guidance_outputs;d concierge.instruction_drafts;ip concierge.instruction_publications;content jsonb;actor uuid;at_time timestamptz;result jsonb;begin
 perform concierge.review_snapshot_current(c,s);select value into item from concierge.review_instruction_entries(c,s->'publication',(s->>'asOfDay')::date) value where value->>'instructionId'=requested::text;
 if item is null then perform concierge.fail('not_found');end if;if (item->>'version')::bigint<>ver or item->>'contentHash'<>hash then perform concierge.fail('guidance_conflict');end if;
 if item->>'format'='authored_schedule' then select * into o from concierge.review_guidance_outputs where id=requested and client_id=c;content:=jsonb_build_object('format','authored_schedule','body',o.body);actor:=(o.publisher->>'actorId')::uuid;at_time:=o.recorded_at;
 else select * into ip from concierge.instruction_publications where id=requested and client_id=c;select * into d from concierge.instruction_drafts where id=ip.draft_id;content:=jsonb_build_object('format','legacy_usage','revision',concierge.review_legacy_instruction_json(d,ip));actor:=ip.actor_id;at_time:=ip.created_at;end if;
 result:=jsonb_build_object('schemaVersion',1,'audience',case when advisor then 'advisor' else 'client' end,'snapshot',s,'item',item,'content',content,'publishedBy',actor,'publishedAt',concierge.care_instant(at_time))||case when advisor then jsonb_build_object('clientId',c) else '{}'::jsonb end;
 if concierge.review_bytes(result)>400000 then perform concierge.fail('invalid_input');end if;return result;
end $$;

-- Preserve the exact reviewed Care body behind one fixed compatibility wrapper.
alter function public.concierge_care_command_v1(jsonb) set schema concierge;
alter function concierge.concierge_care_command_v1(jsonb) rename to review_care_command_before_v1;
revoke all on function concierge.review_care_command_before_v1(jsonb) from public,anon,authenticated,service_role;
create function concierge.review_lossy(c uuid,v integer) returns boolean language sql set search_path='' as $$select exists(select 1 from concierge.review_guidance_outputs o where client_id=c and concierge.review_is_published(o) and (body->'publication'->>'version')::integer=v and (kind<>'instruction' or body->>'effectiveOn'<=to_char((clock_timestamp() at time zone 'America/Chicago')::date,'YYYY-MM-DD'))) or exists(select 1 from concierge.instruction_publications p join concierge.instruction_drafts d on d.id=p.draft_id where p.client_id=c and (d.data->>'planVersion')::integer=v and d.data->>'effectiveOn'<=to_char((clock_timestamp() at time zone 'America/Chicago')::date,'YYYY-MM-DD'))$$;
create function public.concierge_care_command_v1(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;c uuid;begin
 result:=concierge.review_care_command_before_v1(p_command);
 if p_command->>'action' in ('read_client_plan_v2','read_advisor_publication_v2') and result->'plan'<>'null'::jsonb then c:=case when p_command->>'action'='read_client_plan_v2' then auth.uid() else (p_command->>'clientId')::uuid end;if concierge.review_lossy(c,(result->'plan'->>'version')::integer) then perform concierge.fail('guidance_version_required');end if;end if;return result;
end $$;
revoke all on function public.concierge_care_command_v1(jsonb) from public,anon,service_role;grant execute on function public.concierge_care_command_v1(jsonb) to authenticated;

alter function public.concierge_plan_command_v1(jsonb) set schema concierge;
alter function concierge.concierge_plan_command_v1(jsonb) rename to review_plan_command_before_v1;
revoke all on function concierge.review_plan_command_before_v1(jsonb) from public,anon,authenticated,service_role;
create function public.concierge_plan_command_v1(p_command jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a text:=p_command->>'action';c uuid;prior boolean;result jsonb;begin
 if a='record_decision_v1' then
  c:=auth.uid();perform concierge.review_guard(c,false,false);perform pg_advisory_xact_lock(hashtextextended('concierge:request:'||c::text||':'||(p_command->>'requestId'),0));perform pg_advisory_xact_lock(hashtextextended('concierge:client:'||c::text,0));
  select exists(select 1 from concierge.plan_requests where actor_id=c and request_id=(p_command->>'requestId')::uuid) into prior;
  if not prior and concierge.review_lossy(c,(p_command->>'publicationVersion')::integer) then perform concierge.fail('guidance_version_required');end if;
  result:=concierge.review_plan_command_before_v1(p_command);if not prior then perform concierge.review_capture_decision(c,result,c,(p_command->>'requestId')::uuid,'plan_v1');end if;return result;
 end if;
 result:=concierge.review_plan_command_before_v1(p_command);
 if a in ('read_client_plan_v1','read_advisor_publication_v1') and result->'plan'<>'null'::jsonb then c:=case when a='read_client_plan_v1' then auth.uid() else (p_command->>'clientId')::uuid end;if concierge.review_lossy(c,(result->'plan'->>'version')::integer) then perform concierge.fail('guidance_version_required');end if;end if;return result;
end $$;
revoke all on function public.concierge_plan_command_v1(jsonb) from public,anon,service_role;grant execute on function public.concierge_plan_command_v1(jsonb) to authenticated;

create unique index review_guidance_one_output_per_draft on concierge.review_guidance_outputs(draft_id);
create function concierge.review_output_authority(o concierge.review_guidance_outputs) returns void language plpgsql set search_path='' as $$
declare rev concierge.review_guidance_revisions;ap concierge.review_guidance_approvals;pol concierge.plan_policy;rv concierge.review_guidance_reviews;cur jsonb;expected jsonb;begin
 perform concierge.review_guard(o.client_id,true,true,true);perform concierge.capability(auth.uid(),'publish');
 if o.publisher->>'kind'<>'human' or (o.publisher->>'actorId')::uuid is distinct from auth.uid() then perform concierge.fail('forbidden');end if;
 select * into rev from concierge.review_guidance_revisions where draft_id=o.draft_id and revision=o.revision;
 if not found or rev.target is distinct from o.target or rev.body is distinct from o.body or rev.basis is distinct from o.basis or o.target->>'kind'<>o.kind or (o.target->>'clientId')::uuid<>o.client_id then perform concierge.fail('approval_conflict');end if;
 perform concierge.review_require_publication(o.client_id,o.body->'publication',true);cur:=concierge.review_guidance_basis(o.client_id,o.body);expected:=o.basis;
 if o.kind='instruction' and exists(select 1 from concierge.instruction_publications where id=o.id and client_id=o.client_id and draft_id=o.draft_id and version=o.output_version) then expected:=jsonb_set(expected,'{instructionHead}',to_jsonb((o.basis->>'instructionHead')::bigint+1));end if;
 if cur is distinct from expected or jsonb_array_length(concierge.review_guidance_issues(o.client_id,o.body,o.basis,o.basis,true))>0 then perform concierge.fail('basis_conflict');end if;
 select * into pol from concierge.plan_policy where singleton for share;select * into ap from concierge.review_guidance_approvals where id=o.approval_id for update;
 if not found or ap.draft_id<>o.draft_id or ap.revision<>o.revision or ap.target is distinct from o.target or ap.publisher is distinct from o.publisher or ap.scope<>o.kind||'.publish' or ap.policy_revision<>pol.revision or (pol.require_kanuj_approval and ap.approved_by<>pol.owner_actor_id) or exists(select 1 from concierge.review_guidance_revocations where approval_id=ap.id) then perform concierge.fail('approval_conflict');end if;
 if not concierge.plan_read_human_live(ap.approved_by) then perform concierge.fail('approval_conflict');end if;perform concierge.review_guidance_sources_check(o.client_id,o.body,ap.approved_by);perform concierge.review_guidance_publisher(o.client_id,o.publisher,o.body);
 select * into rv from concierge.review_guidance_reviews where draft_id=o.draft_id and revision=o.revision and target=o.target and concierge.plan_read_human_live(actor_id) order by recorded_at desc,id desc limit 1;
 if not found then perform concierge.fail('not_ready');end if;perform concierge.review_guidance_sources_check(o.client_id,o.body,rv.actor_id);
 perform concierge.review_guard(o.client_id,true,true,true);
end $$;
create function concierge.review_canonical_output_guard() returns trigger language plpgsql set search_path='' as $$declare o concierge.review_guidance_outputs;d concierge.instruction_drafts;output_kind text;begin
 if (select activated from concierge.plan_policy where singleton) is distinct from true then return new;end if;
 output_kind:=case TG_TABLE_NAME when 'service_reviews' then 'review' when 'instruction_publications' then 'instruction' else 'reply' end;
 select * into o from concierge.review_guidance_outputs where id=new.id and client_id=new.client_id and review_guidance_outputs.kind=output_kind;
 if not found then perform concierge.fail('content_version_required');end if;perform concierge.review_output_authority(o);
 if output_kind='review' then if new.data is distinct from o.body or new.actor_id is distinct from (o.publisher->>'actorId')::uuid or new.recorded_at is distinct from o.recorded_at then perform concierge.fail('approval_conflict');end if;
 elsif output_kind='instruction' then
  select * into d from concierge.instruction_drafts where id=new.draft_id and client_id=new.client_id;
  if not found or new.draft_id<>o.draft_id or new.version<>o.output_version or d.data is distinct from o.body or new.actor_id is distinct from (o.publisher->>'actorId')::uuid or new.created_at is distinct from o.recorded_at then perform concierge.fail('approval_conflict');end if;
 else if new.report_id is distinct from (o.body->'reportRef'->>'id')::uuid or to_jsonb(new.reply) is distinct from o.body->'reply' or new.created_by is distinct from (o.publisher->>'actorId')::uuid or new.created_at is distinct from o.recorded_at then perform concierge.fail('approval_conflict');end if;end if;
 return new;
end $$;
drop trigger plan_review_barrier on concierge.service_reviews;
drop trigger plan_instruction_barrier on concierge.instruction_publications;
drop trigger plan_reply_barrier on concierge.checkin_replies;
create trigger plan_review_barrier before insert on concierge.service_reviews for each row execute function concierge.review_canonical_output_guard();
create trigger plan_instruction_barrier before insert on concierge.instruction_publications for each row execute function concierge.review_canonical_output_guard();
create trigger plan_reply_barrier before insert on concierge.checkin_replies for each row execute function concierge.review_canonical_output_guard();
create function concierge.review_output_complete() returns trigger language plpgsql security definer set search_path='' as $$declare o concierge.review_guidance_outputs;receipt concierge.review_guidance_receipts;event concierge.plan_events;canonical boolean;begin
 select * into o from concierge.review_guidance_outputs where id=new.id;perform concierge.review_output_authority(o);
 select * into receipt from concierge.review_guidance_receipts where id=o.receipt_id;
 if not found or receipt.client_id<>o.client_id or receipt.output_id<>o.id or receipt.approval_id<>o.approval_id or receipt.event_id<>o.event_id or receipt.actor_id is distinct from auth.uid() then perform concierge.fail('incomplete_publication');end if;
 perform concierge.plan_shape(receipt.receipt,concierge.review_shapes()->'guidanceReceipt');
 if receipt.receipt->'target' is distinct from o.target or receipt.receipt->'publisher' is distinct from o.publisher or receipt.receipt->'record' is distinct from jsonb_build_object('kind',o.kind,'id',o.id) or receipt.receipt->>'approvalId'<>o.approval_id::text or receipt.receipt->>'receiptId'<>o.receipt_id::text or receipt.receipt->>'notificationEventId'<>o.event_id::text or receipt.receipt->>'requestId'<>receipt.request_id::text or receipt.receipt->>'publishedAt'<>concierge.care_instant(o.recorded_at) then perform concierge.fail('incomplete_publication');end if;
 select * into event from concierge.plan_events where id=o.event_id;
 if not found or event.client_id<>o.client_id or event.publication_version<>(o.body->'publication'->>'version')::integer or event.source_kind<>'guidance' or event.source_id<>o.id or event.source_version<>o.output_version or event.kind<>o.kind||'_published' then perform concierge.fail('incomplete_publication');end if;
 if (select count(*) from concierge.plan_deliveries where event_id=o.event_id)<>2 or (select count(*) from concierge.plan_deliveries where event_id=o.event_id and recipient_id=o.client_id and channel in ('portal','email'))<>2 then perform concierge.fail('incomplete_publication');end if;
 canonical:=case o.kind when 'review' then exists(select 1 from concierge.service_reviews where id=o.id and client_id=o.client_id and data=o.body and actor_id=(o.publisher->>'actorId')::uuid and recorded_at=o.recorded_at)
 when 'instruction' then exists(select 1 from concierge.instruction_publications p join concierge.instruction_drafts d on d.id=p.draft_id where p.id=o.id and p.client_id=o.client_id and p.draft_id=o.draft_id and p.version=o.output_version and d.data=o.body and p.actor_id=(o.publisher->>'actorId')::uuid and p.created_at=o.recorded_at)
 else exists(select 1 from concierge.checkin_replies where id=o.id and client_id=o.client_id and report_id=(o.body->'reportRef'->>'id')::uuid and reply=o.body->>'reply' and created_by=(o.publisher->>'actorId')::uuid and created_at=o.recorded_at) end;
 if canonical is not true or not exists(select 1 from concierge.review_requests where actor_id=receipt.actor_id and request_id=receipt.request_id and client_id=o.client_id and family='guidance' and command->>'action'='publish_guidance_v1' and command->'target'=o.target and command->>'approvalId'=o.approval_id::text and result=receipt.receipt) then perform concierge.fail('incomplete_publication');end if;
 return null;
end $$;
create constraint trigger review_output_complete after insert on concierge.review_guidance_outputs deferrable initially deferred for each row execute function concierge.review_output_complete();
create function concierge.review_attention_complete() returns trigger language plpgsql security definer set search_path='' as $$declare a concierge.review_attention;o concierge.review_guidance_outputs;am concierge.review_report_amendments;begin
 select * into a from concierge.review_attention where id=new.attention_id;select * into o from concierge.review_guidance_outputs where id=a.prior_review_id;select * into am from concierge.review_report_amendments where id=a.amendment_id;
 if a.id is null or o.kind is distinct from 'review' or o.client_id is distinct from a.client_id or am.client_id is distinct from a.client_id or (o.body->'publication'->>'version')::integer is distinct from a.publication_version or not exists(select 1 from jsonb_array_elements(o.basis->'references') refs where refs->'event'=jsonb_build_object('kind',am.report_kind,'id',am.report_id)) then perform concierge.fail('incomplete_publication');end if;
 if new.resolved_by is not null then
  select * into o from concierge.review_guidance_outputs where id=new.resolved_by;if not found or o.kind<>'review' or o.client_id<>a.client_id or not exists(select 1 from jsonb_array_elements(o.basis->'references') refs where refs->'event'=jsonb_build_object('kind',am.report_kind,'id',am.report_id) and refs->'amendmentHeadId'<>'null'::jsonb) then perform concierge.fail('incomplete_publication');end if;
 end if;return null;
end $$;
create constraint trigger review_attention_complete after insert on concierge.review_attention_events deferrable initially deferred for each row execute function concierge.review_attention_complete();
create function concierge.review_guidance_publish(d concierge.review_guidance_drafts,rev concierge.review_guidance_revisions,cmd jsonb) returns jsonb language plpgsql set search_path='' as $$
declare o concierge.review_guidance_outputs;ap concierge.review_guidance_approvals;basis jsonb;previous concierge.review_guidance_outputs;ver bigint:=1;at_time timestamptz;start jsonb;state jsonb;id uuid:=gen_random_uuid();receipt_id uuid:=gen_random_uuid();event_id uuid;result jsonb;r record;begin
 if exists(select 1 from concierge.review_guidance_outputs where draft_id=d.id or approval_id=(cmd->>'approvalId')::uuid) then perform concierge.fail('approval_conflict');end if;
 select * into ap from concierge.review_guidance_approvals where review_guidance_approvals.id=(cmd->>'approvalId')::uuid for update;if not found then perform concierge.fail('approval_conflict');end if;
 basis:=concierge.review_guidance_basis(d.client_id,rev.body);if basis is distinct from rev.basis then perform concierge.fail('basis_conflict');end if;
 if d.kind='instruction' then
  select * into previous from concierge.review_guidance_outputs x where x.client_id=d.client_id and x.kind='instruction' and x.body->'publication'=rev.body->'publication' and x.body->'slotId'=rev.body->'slotId' and x.body->'productId'=rev.body->'productId' order by output_version desc limit 1;
  if (rev.body->>'baseInstructionVersion')::bigint<>coalesce(previous.output_version,0) or nullif(rev.body->'baseInstructionId','null'::jsonb) is distinct from to_jsonb(previous.id) then perform concierge.fail('guidance_conflict');end if;ver:=coalesce(previous.output_version,0)+1;
  state:=concierge.review_scope_check(d.client_id,rev.body);if state is not null then start:=state->'originalStart';end if;
 end if;
 at_time:=clock_timestamp();
 o:=row(id,d.client_id,d.kind,d.id,d.revision,ap.id,rev.body,rev.basis,rev.target,cmd->'publisher',receipt_id,gen_random_uuid(),ver,start,at_time)::concierge.review_guidance_outputs;
 perform concierge.review_output_authority(o);
 event_id:=concierge.review_notify(d.client_id,id,(rev.body->'publication'->>'version')::integer,ver,d.kind||'_published',d.client_id);o.event_id:=event_id;
 insert into concierge.review_guidance_outputs select o.*;
 if d.kind='review' then insert into concierge.service_reviews(id,client_id,data,actor_id,recorded_at) values(id,d.client_id,rev.body,auth.uid(),at_time);
 elsif d.kind='instruction' then
  insert into concierge.instruction_drafts(id,client_id,data,source,original_started_on,actor_id,created_at) values(d.id,d.client_id,rev.body,jsonb_build_object('kind','v3','publicationVersion',rev.body->'publication'->'version','productId',rev.body->'productId','slotId',rev.body->'slotId'),case when start->>'state'='known' then (start->>'value')::date end,auth.uid(),at_time);
  insert into concierge.instruction_publications(id,client_id,draft_id,version,actor_id,created_at) values(id,d.client_id,d.id,ver,auth.uid(),at_time);
 else insert into concierge.checkin_replies(id,client_id,report_id,reply,created_by,created_at) values(id,d.client_id,(rev.body->'reportRef'->>'id')::uuid,rev.body->>'reply',auth.uid(),at_time);end if;
 insert into concierge.service_heads values(d.client_id,0) on conflict do nothing;update concierge.service_heads set revision=revision+1 where client_id=d.client_id;
 if d.kind='review' then
  insert into concierge.checkin_heads(client_id,revision,next_checkin_on) values(d.client_id,0,(rev.body->>'nextReviewOn')::date) on conflict(client_id) do update set next_checkin_on=excluded.next_checkin_on;
  for r in select a.id from concierge.review_attention a join concierge.review_report_amendments am on am.id=a.amendment_id where a.client_id=d.client_id and not exists(select 1 from concierge.review_attention_events where attention_id=a.id and resolved_by is not null) and exists(select 1 from jsonb_array_elements(rev.basis->'references') refs where refs->'event'=jsonb_build_object('kind',am.report_kind,'id',am.report_id) and refs->'amendmentHeadId'<>'null'::jsonb) loop insert into concierge.review_attention_events values(gen_random_uuid(),r.id,id,at_time);end loop;
 end if;
 result:=jsonb_build_object('requestId',cmd->'requestId','receiptId',receipt_id,'target',rev.target,'approvalId',ap.id,'publisher',cmd->'publisher','record',jsonb_build_object('kind',d.kind,'id',id),'publishedAt',concierge.care_instant(at_time),'notificationEventId',event_id);
 insert into concierge.review_guidance_receipts values(receipt_id,d.client_id,id,ap.id,event_id,auth.uid(),(cmd->>'requestId')::uuid,result);return result;
end $$;

