 result:=concierge.review_checkin_advisor_read_before_v1(p_client_id);
 if (select activated from concierge.plan_policy where singleton) and (exists(select 1 from concierge.checkin_reports where client_id=p_client_id and report_format='goal') or exists(select 1 from concierge.review_report_amendments where client_id=p_client_id) or exists(select 1 from concierge.review_conversations where client_id=p_client_id) or exists(select 1 from concierge.review_private_notes where client_id=p_client_id)) then perform concierge.fail('content_version_required');end if;return result;
end $$;
