alter function concierge.concierge_checkin_write(uuid,text,bigint,uuid,jsonb) rename to review_checkin_write_before_v1;
revoke all on function concierge.review_checkin_write_before_v1(uuid,text,bigint,uuid,jsonb) from public,anon,authenticated,service_role;
create function public.concierge_checkin_write(p_client_id uuid,p_action text,p_expected_revision bigint,p_request_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;prior boolean;begin
 select exists(select 1 from concierge.workflow_requests where actor_id=auth.uid() and request_id=p_request_id and client_id=p_client_id) into prior;
 if not prior and p_action='submit_report' and (select activated from concierge.plan_policy where singleton) then perform concierge.review_guard(p_client_id,false,true);perform concierge.fail('content_version_required');end if;
 result:=concierge.review_checkin_write_before_v1(p_client_id,p_action,p_expected_revision,p_request_id,p_payload);
 if not prior and p_action='add_meeting_note' and (select activated from concierge.plan_policy where singleton) and exists(select 1 from concierge.checkin_reports where id=(p_payload->>'checkinId')::uuid and client_id=p_client_id and report_format='goal') then perform concierge.fail('content_version_required');end if;return result;
end $$;
revoke all on function public.concierge_checkin_write(uuid,text,bigint,uuid,jsonb) from public,anon,service_role;grant execute on function public.concierge_checkin_write(uuid,text,bigint,uuid,jsonb) to authenticated;
alter function public.concierge_service_client_view() set schema concierge;
alter function concierge.concierge_service_client_view() rename to review_service_client_before_v1;
alter function public.concierge_service_advisor_view(uuid) set schema concierge;
alter function concierge.concierge_service_advisor_view(uuid) rename to review_service_advisor_before_v1;
revoke all on function concierge.review_service_client_before_v1(),concierge.review_service_advisor_before_v1(uuid) from public,anon,authenticated,service_role;
create function concierge.review_service_lossy(c uuid,result jsonb) returns boolean language sql set search_path='' as $$select (auth.uid() is distinct from c or (exists(select 1 from concierge.entitled_publications where client_id=c) and concierge.plan_care_window(c)<>'expired')) and exists(select 1 from concierge.review_guidance_outputs o where o.client_id=c and o.kind in ('review','instruction') and concierge.review_is_published(o))$$;
create function public.concierge_service_client_view() returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin result:=concierge.review_service_client_before_v1();if concierge.review_service_lossy(auth.uid(),result) then perform concierge.fail('content_version_required');end if;return result;end $$;
create function public.concierge_service_advisor_view(p_client_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin result:=concierge.review_service_advisor_before_v1(p_client_id);if concierge.review_service_lossy(p_client_id,result) then perform concierge.fail('content_version_required');end if;return result;end $$;
revoke all on function public.concierge_service_client_view(),public.concierge_service_advisor_view(uuid) from public,anon,service_role;grant execute on function public.concierge_service_client_view(),public.concierge_service_advisor_view(uuid) to authenticated;
-- A legacy decision writer may not compete with a canonical decision or omit new guidance.
alter function public.concierge_write(uuid,text,bigint,uuid,jsonb) set schema concierge;
alter function concierge.concierge_write(uuid,text,bigint,uuid,jsonb) rename to review_legacy_write_before_v1;
revoke all on function concierge.review_legacy_write_before_v1(uuid,text,bigint,uuid,jsonb) from public,anon,authenticated,service_role;
create function public.concierge_write(p_client_id uuid,p_action text,p_expected_revision bigint,p_request_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;prior boolean;v integer;begin
 select exists(select 1 from concierge.requests where actor_id=auth.uid() and request_id=p_request_id and client_id=p_client_id) into prior;
 result:=concierge.review_legacy_write_before_v1(p_client_id,p_action,p_expected_revision,p_request_id,p_payload);
 if not prior and p_action='decide' and (select activated from concierge.plan_policy where singleton) then
  select published_version into v from concierge.cases where client_id=p_client_id;
  if exists(select 1 from concierge.plan_decisions where client_id=p_client_id and version=v) or exists(select 1 from concierge.review_guidance_outputs o where o.client_id=p_client_id and (o.body->'publication'->>'version')::integer=v and concierge.review_is_published(o) and (o.kind<>'instruction' or o.body->>'effectiveOn'<=to_char((clock_timestamp() at time zone 'America/Chicago')::date,'YYYY-MM-DD'))) then perform concierge.fail('content_version_required');end if;
 end if;return result;
end $$;
revoke all on function public.concierge_write(uuid,text,bigint,uuid,jsonb) from public,anon,service_role;grant execute on function public.concierge_write(uuid,text,bigint,uuid,jsonb) to authenticated;

-- Private tables/helpers have no raw or service-role execute path.
do $$declare t text;f regprocedure;begin
 for t in select tablename from pg_tables where schemaname='concierge' and tablename like 'review_%' loop execute format('alter table concierge.%I enable row level security',t);execute format('revoke all on concierge.%I from public,anon,authenticated,service_role',t);end loop;
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and (p.proname like 'review_%' or p.proname='guidance_command_fields') loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f);end loop;
end $$;
revoke all on function public.concierge_review_command_v1(jsonb) from public,anon,service_role;
grant execute on function public.concierge_review_command_v1(jsonb) to authenticated;
revoke all on function public.concierge_guidance_command_v1(jsonb) from public,anon,service_role;
grant execute on function public.concierge_guidance_command_v1(jsonb) to authenticated;
commit;
